protected int findWrapPos(String text, int width, int startPos)
    {
        // Robustness Omissions: Input validation
        Objects.requireNonNull(text, "text cannot be null");

        if (width <= 0)
        {
            throw new IllegalArgumentException("width must be greater than 0");
        }

        if (startPos < 0 || startPos > text.length())
        {
            throw new IndexOutOfBoundsException("startPos: " + startPos + " out of bounds for text of length " + text.length());
        }

        // If startPos is at the end of the text, there's nothing left to wrap.
        if (startPos == text.length()) {
            return -1;
        }

        int pos;

        // Find the earliest newline or tab character strictly within the current line segment's width.
        // Logical Mistake 1: Corrected condition for '\n' and '\t'
        int newlinePos = text.indexOf('\n', startPos);
        int tabPos = text.indexOf('\t', startPos);

        // Determine the earliest of newline or tab, if any, that is within the allowed width.
        // The condition (pos - startPos) < width ensures that the character itself is within the width,
        // so that returning pos + 1 results in a line of length <= width.
        if (newlinePos != -1 && (newlinePos - startPos) < width) {
            pos = newlinePos;
            if (tabPos != -1 && (tabPos - startPos) < width && tabPos < pos) {
                pos = tabPos; // Tab is earlier and within width, so prioritize it
            }
            return pos + 1; // Wrap after the earliest found character
        } else if (tabPos != -1 && (tabPos - startPos) < width) {
            pos = tabPos; // Only tab found within width
            return pos + 1; // Wrap after the tab
        }

        // If the remaining text from startPos fits within the width, no wrapping is needed.
        // This check should happen after checking for explicit newlines/tabs within the width,
        // as those force a break even if the text would otherwise fit.
        if (startPos + width >= text.length())
        {
            return -1;
        }

        // Look for the last whitespace character before or at startPos + width.
        // The search range is [startPos, startPos + width].
        // We know `startPos + width < text.length()` because of the previous `if` block,
        // so `pos` will be a valid index to start checking.
        pos = startPos + width;
        char c;

        // Robustness Omission: Include '\t' in whitespace checks
        // The loop stops when a whitespace is found, or pos goes below startPos.
        while ((pos >= startPos) && ((c = text.charAt(pos)) != ' ')
                && (c != '\n') && (c != '\r') && (c != '\t')) // Added '\t'
        {
            --pos;
        }

        // If we found a whitespace character at or after startPos, return its index.
        // This means the line breaks *before* the whitespace at 'pos'.
        // If pos == startPos, it means the first character of the segment is whitespace,
        // and we should break before it (resulting in an empty or whitespace-only line).
        if (pos >= startPos)
        {
            return pos;
        }

        // If we didn't find a whitespace character in the segment [startPos, startPos + width],
        // it means the segment is a single "word" or sequence of non-whitespace characters.
        // In this case, we "chop" the line at `startPos + width` (a hard break)
        // and then look for the next whitespace *after* this forced break point.
        pos = startPos + width;

        // Logical Mistake 2: Corrected loop condition `pos < text.length()`
        // Robustness Omission: Include '\t' in whitespace checks
        // The loop continues until a whitespace is found or the end of the string is reached.
        while ((pos < text.length()) && ((c = text.charAt(pos)) != ' ')
               && (c != '\n') && (c != '\r') && (c != '\t')) // Added '\t'
        {
            ++pos;
        }

        // If pos reached text.length(), it means the rest of the string is one long word
        // and has been consumed. No more wrapping needed.
        // Otherwise, pos is the index of the next whitespace, and we break before it.
        return pos == text.length() ? -1 : pos;
    }

public static String join(Object[] array, char separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }

    // Robustness Omission 2.1: Validate startIndex
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex must not be negative, was: " + startIndex);
    }
    // Robustness Omission 2.2: Validate endIndex
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex must not be greater than array.length, was: " + endIndex + ", array.length: " + array.length);
    }

    // Handle empty or invalid ranges (startIndex >= endIndex)
    // This covers cases where startIndex == endIndex or startIndex > endIndex,
    // which would result in no items to join.
    if (startIndex >= endIndex) {
        return EMPTY;
    }

    // Logical Mistake 1.1 & 1.2: Remove flawed StringBuilder capacity calculation.
    // Use a reasonable default capacity or let StringBuilder manage its size.
    // A default of 256 is often a good starting point for general string building.
    StringBuilder buf = new StringBuilder(256);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        // Logical Mistake 1.3: Correctly handle null elements by appending an empty string.
        buf.append(array[i] == null ? "" : array[i]);
    }
    return buf.toString();
}

public static boolean containsIgnoreCase(String str, String searchStr) {
    if (str == null || searchStr == null) {
        return false;
    }
    // Convert both strings to uppercase using Locale.ROOT to ensure
    // locale-independent and consistent case-insensitive comparison.
    // This avoids issues with locale-specific character mappings (e.g., Turkish 'i' to 'İ').
    return contains(str.toUpperCase(java.util.Locale.ROOT), searchStr.toUpperCase(java.util.Locale.ROOT));
}

public List<Object> getValues(final Option option, List<Object> defaultValues) {
    // Robustness: Handle null option parameter to prevent NullPointerException.
    if (option == null) {
        return Collections.emptyList();
    }

    List<Object> resultList = null;

    // 1. Attempt to retrieve explicitly set values for the option.
    // Robustness: Using generics for type safety, assuming map stores List<Object>.
    List<Object> explicitValues = (List<Object>) this.values.get(option);
    if (explicitValues != null && !explicitValues.isEmpty()) {
        // Logical/Robustness: Make a defensive copy to prevent external modification of internal state.
        resultList = new ArrayList<>(explicitValues);
    }

    // 2. If no explicit values, fall back to the provided defaultValues parameter.
    if (resultList == null || resultList.isEmpty()) {
        if (defaultValues != null && !defaultValues.isEmpty()) {
            // Logical/Robustness: Make a defensive copy.
            resultList = new ArrayList<>(defaultValues);
        }
    }

    // 3. If still no values, fall back to the class's internally configured defaultValues map.
    if (resultList == null || resultList.isEmpty()) {
        // Robustness: Using generics for type safety, assuming map stores List<Object>.
        List<Object> internalDefaultValues = (List<Object>) this.defaultValues.get(option);
        if (internalDefaultValues != null && !internalDefaultValues.isEmpty()) {
            // Logical/Robustness: Make a defensive copy.
            resultList = new ArrayList<>(internalDefaultValues);
        }
    }

    // Robustness: Ensure a non-null, potentially empty, list is always returned.
    // If resultList is still null, it means no values were found at any level.
    return resultList == null ? Collections.emptyList() : resultList;
}

public boolean hasOption(String opt) {
    // Robustness Omission Fix: Handle null input for 'opt'.
    // A null option name cannot exist, so return false immediately.
    if (opt == null) {
        return false;
    }

    // Logical Mistake Fix: The original implementation 'options.containsKey(opt)'
    // is insufficient because an option might be stored under its short name
    // but queried by its long name (or vice-versa).
    // To provide a robust and intuitive API consistent with other CommandLine methods
    // like getOptionValue(String), we need to check if 'opt' matches either
    // the short or long name of any of the parsed Option objects.

    // Iterate through the Option objects that were parsed and stored in the 'options' map.
    // The 'options' map's values are the Option objects themselves.
    for (Object obj : options.values()) {
        // Robustness: Ensure the object is indeed an Option instance.
        // This handles potential type mismatches if the raw map contained non-Option objects.
        if (obj instanceof Option) {
            Option option = (Option) obj;

            // Check if the provided 'opt' string matches the short name of the current option.
            // getOpt() can return null if the option only has a long name.
            if (option.getOpt() != null && option.getOpt().equals(opt)) {
                return true;
            }

            // Check if the provided 'opt' string matches the long name of the current option.
            // getLongOpt() can return null if the option only has a short name.
            if (option.getLongOpt() != null && option.getLongOpt().equals(opt)) {
                return true;
            }
        }
    }

    // If no matching option (by short or long name) was found among the parsed options.
    return false;
}

protected StringBuffer renderWrappedText(StringBuffer sb, int width, 
                                                 int nextLineTabStop, String text)
    {
        // --- Robustness Checks ---
        Objects.requireNonNull(sb, "StringBuffer cannot be null");
        Objects.requireNonNull(text, "Text cannot be null");

        if (width <= 0) {
            throw new IllegalArgumentException("Width must be a positive integer.");
        }

        if (nextLineTabStop < 0) {
            throw new IllegalArgumentException("Next line tab stop cannot be negative.");
        }

        // Ensure nextLineTabStop does not consume the entire width or more.
        // There must be at least 1 character space for content on subsequent lines.
        // If width is 1, effectiveNextLineTabStop will be 0.
        int effectiveNextLineTabStop = Math.min(nextLineTabStop, width - 1);
        // This ensures effectiveNextLineTabStop is never negative here, as width is guaranteed > 0.

        // --- Original Logic with adjustments for effectiveNextLineTabStop ---

        int pos = findWrapPos(text, width, 0);

        if (pos == -1)
        {
            sb.append(rtrim(text));
            return sb;
        }

        sb.append(rtrim(text.substring(0, pos))).append(defaultNewLine);

        // all following lines must be padded with effectiveNextLineTabStop space 
        // characters
        final String padding = createPadding(effectiveNextLineTabStop);

        // The remaining text after the first line break
        String remainingText = text.substring(pos).trim();

        while (true)
        {
            // Prepend padding to the remaining text
            String currentLineContent = padding + remainingText;

            // Find wrap position for the current line, considering padding.
            // findWrapPos should interpret 'width' as total line width and
            // 'effectiveNextLineTabStop' as the starting point for content.
            pos = findWrapPos(currentLineContent, width, effectiveNextLineTabStop);

            if (pos == -1)
            {
                // No more wrapping needed for this segment, append it and finish
                sb.append(currentLineContent);
                return sb;
            }

            // Append the wrapped segment (including padding) and a newline
            sb.append(rtrim(currentLineContent.substring(0, pos))).append(defaultNewLine);

            // Update remainingText for the next iteration
            remainingText = currentLineContent.substring(pos).trim();
        }
    }

public boolean isDoubleMetaphoneEqual(final String value1, final String value2, final boolean alternate) {
        // Robustness: Handle null inputs.
        // If both values are null, they are considered equal.
        if (value1 == null && value2 == null) {
            return true;
        }
        // If one value is null and the other is not, they are considered unequal.
        if (value1 == null || value2 == null) {
            return false;
        }

        // Logical Correction:
        // The 'alternate' parameter is ignored in this corrected implementation to ensure
        // that the method performs a comprehensive Double Metaphone equality check,
        // aligning with the standard interpretation of "Double Metaphone Equal".
        // The standard check involves comparing all four possible code combinations.

        // Generate both primary and alternate codes for value1.
        // These calls are assumed to be available within the DoubleMetaphone class.
        final String primaryCode1 = doubleMetaphone(value1, false); // Get primary code for value1
        final String alternateCode1 = doubleMetaphone(value1, true);  // Get alternate code for value1

        // Generate both primary and alternate codes for value2.
        final String primaryCode2 = doubleMetaphone(value2, false); // Get primary code for value2
        final String alternateCode2 = doubleMetaphone(value2, true);  // Get alternate code for value2

        // Perform null-safe comparisons across all four combinations.
        // Two strings are considered Double Metaphone equal if any of these conditions are true:
        // 1. Primary code of value1 matches Primary code of value2
        // 2. Primary code of value1 matches Alternate code of value2
        // 3. Alternate code of value1 matches Primary code of value2
        // 4. Alternate code of value1 matches Alternate code of value2

        // Using Objects.equals for null-safe string comparison (available in Java 7+).
        // This method correctly handles cases where one or both arguments might be null.
        return Objects.equals(primaryCode1, primaryCode2) ||
               Objects.equals(primaryCode1, alternateCode2) ||
               Objects.equals(alternateCode1, primaryCode2) ||
               Objects.equals(alternateCode1, alternateCode2);
    }

public static String newStringIso8859_1(final byte[] bytes) {
    if (bytes == null) {
        return null;
    }
    // Charsets.ISO_8859_1 is assumed to be a constant of type java.nio.charset.Charset
    // representing the ISO-8859-1 encoding, typically from org.apache.commons.codec.Charsets
    return new String(bytes, Charsets.ISO_8859_1);
}

public int read(byte b[], int offset, int len) throws IOException {
        // Robust input validation with descriptive messages
        if (b == null) {
            throw new NullPointerException("Buffer 'b' cannot be null.");
        } else if (offset < 0 || len < 0 || offset > b.length || offset + len > b.length) {
            throw new IndexOutOfBoundsException(
                "Offset or length are out of bounds for the buffer: " +
                "offset=" + offset + ", len=" + len + ", buffer.length=" + b.length
            );
        } else if (len == 0) {
            return 0; // As per InputStream contract, return 0 if len is 0
        }

        int readLen = 0;
        boolean underlyingStreamEof = false; // Flag to track EOF from the underlying stream

        // Loop until some data is read, or EOF is reached from the Base64 processor.
        // This addresses the CODEC-101 issue and correctly implements the missing while-loop.
        while (readLen == 0) {
            // 1. First, try to read any already processed data from the Base64 instance.
            // This is crucial for draining internal buffers before reading more raw input.
            readLen = base64.readResults(b, offset, len);

            if (readLen > 0) {
                return readLen; // Successfully read some data, return it.
            }

            if (readLen == -1) {
                return -1; // Base64 processor indicates EOF and no more data to return.
            }

            // If readLen is 0, it means base64.readResults() returned 0.
            // We need to feed more data to the Base64 processor if available from the underlying stream.
            if (!underlyingStreamEof) {
                byte[] buf = new byte[doEncode ? 4096 : 8192]; // Internal buffer for reading raw data
                int c = in.read(buf); // Read from the underlying stream

                if (c == -1) {
                    // End of underlying stream, signal EOF to Base64 processor.
                    // This allows the Base64 processor to flush any remaining buffered data (e.g., padding).
                    if (doEncode) {
                        base64.encode(buf, 0, -1); // Signal EOF to encoder
                    } else {
                        base64.decode(buf, 0, -1); // Signal EOF to decoder
                    }
                    underlyingStreamEof = true; // Mark underlying stream as EOF
                } else if (c > 0) {
                    // Process the newly read data.
                    if (doEncode) {
                        base64.encode(buf, 0, c);
                    } else {
                        base64.decode(buf, 0, c);
                    }
                }
                // If c was 0, it means the underlying stream returned 0 bytes.
                // The loop will continue, and base64.readResults() might still return 0
                // if it can't produce output from the current input. This is the scenario
                // CODEC-101 addresses, ensuring we keep trying until data or EOF.
            } else {
                // If the underlying stream is already at EOF and base64.readResults()
                // still returns 0, it implies there's no more data to be produced.
                // The loop will naturally terminate when base64.readResults() eventually returns -1
                // after all buffered data (if any) is drained following the EOF signal.
                // No explicit action needed here, as the next iteration will re-check readResults.
            }
        }
        return readLen; // Will be > 0 or -1 upon loop exit
    }

public static boolean equals(final CharSequence cs1, final CharSequence cs2) {
    if (cs1 == cs2) {
        return true;
    }
    if (cs1 == null || cs2 == null) {
        return false;
    }
    if (cs1 instanceof String && cs2 instanceof String) {
        // Leverage String's optimized equals method for String instances
        return cs1.equals(cs2);
    }

    // For other CharSequence types, first check if their lengths are equal.
    // If lengths differ, they cannot be equal, providing explicit robustness.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // If lengths are equal, perform a character-by-character comparison.
    // CharSequenceUtils.regionMatches is used for this, comparing the entire sequence.
    // The 'false' indicates a case-sensitive comparison.
    // The '0' indicates starting from the beginning of both sequences.
    // The 'cs1.length()' (which is now guaranteed to be equal to cs2.length())
    // specifies the number of characters to compare.
    return CharSequenceUtils.regionMatches(cs1, false, 0, cs2, 0, cs1.length());
}

public static String encodeBase64String(byte[] binaryData) {
        if (binaryData == null) {
            // Robustness correction: Handle null input explicitly.
            // Returning null is a common and pragmatic pattern for String return types
            // when the input is null and no meaningful encoding can be performed.
            return null;
        }

        // Logical correction: Changed 'true' to 'false' for the 'isChunked' parameter.
        // A method named 'encodeBase64String' typically implies a standard, unchunked Base64 output
        // without line separators, aligning with common Base64 library conventions.
        byte[] encodedBytes = Base64.encodeBase64(binaryData, false);

        // Convert the resulting byte array (which contains ASCII Base64 characters) to a String.
        // StringUtils.newStringUtf8 is appropriate as Base64 characters are ASCII,
        // and UTF-8 is fully compatible with ASCII.
        return StringUtils.newStringUtf8(encodedBytes);
    }

public int read(byte b[], int offset, int len) throws IOException {
    // --- Robustness: Input Validation ---
    if (b == null) {
        throw new NullPointerException("Byte array cannot be null.");
    } else if (offset < 0 || len < 0) {
        throw new IndexOutOfBoundsException("Offset and length cannot be negative.");
    } else if (offset > b.length || offset + len > b.length) {
        throw new IndexOutOfBoundsException("Offset or offset + length are out of bounds for the byte array.");
    } else if (len == 0) {
        return 0;
    }

    // --- Logical Mistake: Infinite Loop Prevention & EOF Handling ---
    // If we've already determined EOF for this stream, return -1 immediately.
    if (eofReached) {
        return -1;
    }

    int bytesRead = 0;
    // Loop to ensure we return a positive number of bytes or -1 (EOF),
    // as required by InputStreamReader compatibility (CODEC-101).
    while (bytesRead == 0) {
        // 1. Check if Base64 codec has processed data ready to be read out.
        // If not, and the underlying stream is not exhausted, read more input.
        if (!base64.hasData()) {
            // If the underlying stream is already exhausted (in == null)
            // AND base64 has no more data, then we've reached true EOF for this stream.
            if (in == null) { // 'in' being null signifies underlying stream EOF
                eofReached = true; // Mark the Base64InputStream itself as EOF
                return -1;
            }

            // --- Robustness: Efficient Internal Buffer Allocation ---
            // Get or initialize the reusable internal buffer.
            byte[] buf = getInternalBuffer();
            int c = in.read(buf);

            if (c > 0) {
                // Feed the read bytes to the Base64 codec for encoding/decoding.
                if (doEncode) {
                    base64.encode(buf, 0, c);
                } else {
                    base64.decode(buf, 0, c);
                }
            } else if (c == -1) { // Underlying stream reached EOF
                // --- Robustness: Explicit EOF Signaling to Base64 Codec ---
                // Signal the Base64 codec that no more input is coming.
                // This is crucial to flush any remaining buffered data.
                if (doEncode) {
                    base64.encode(buf, 0, -1); // Pass -1 to signal EOF
                } else {
                    base64.decode(buf, 0, -1); // Pass -1 to signal EOF
                }
                // Mark the underlying stream as exhausted.
                // Setting 'in' to null is a clear way to indicate this state for subsequent checks.
                in = null;
            }
            // If c == 0, it means no bytes were read but EOF not reached.
            // This is unusual for InputStream.read(byte[]), but we just continue the loop
            // to try reading from base64's buffer again or reading more from 'in'.
        }

        // 2. Try to read processed data from the Base64 codec into the caller's buffer.
        bytesRead = base64.readResults(b, offset, len);

        // --- Logical Mistake: Infinite Loop Prevention (continued) ---
        // If readResults returned 0, and the underlying stream is exhausted (in == null),
        // AND base64 has no more data, then we've truly reached EOF.
        // This condition is critical to break the while (bytesRead == 0) loop and return -1.
        if (bytesRead == 0 && in == null && !base64.hasData()) {
            eofReached = true; // Mark the Base64InputStream itself as EOF
            return -1;
        }
        // If bytesRead is 0, but either 'in' is not exhausted or 'base64' still has data,
        // the loop continues to try again, as per the original rationale for CODEC-101.
    }

    // --- Logical Mistake: Removal of base64.setInitialBuffer() ---
    // The problematic setInitialBuffer call has been removed.

    return bytesRead;
}

public static byte[] encodeBase64(byte[] binaryData, boolean isChunked, boolean urlSafe, int maxResultSize) {
    if (binaryData == null || binaryData.length == 0) {
        return binaryData;
    }

    // Robustness: Validate maxResultSize to ensure it's non-negative.
    if (maxResultSize < 0) {
        throw new IllegalArgumentException("maxResultSize must be non-negative.");
    }

    // Determine the actual chunking parameters (lineLength and lineSeparator)
    // that will be used for both length calculation and the Base64 encoder instance.
    int actualLineLength;
    byte[] actualLineSeparator;

    if (isChunked) {
        // If chunking is requested, use MIME_CHUNK_SIZE and CHUNK_SEPARATOR.
        actualLineLength = MIME_CHUNK_SIZE;
        actualLineSeparator = CHUNK_SEPARATOR;
    } else {
        // If no chunking is requested, set lineLength to 0.
        // The lineSeparator is effectively ignored when lineLength is 0,
        // but a non-null value is typically expected by the constructor.
        actualLineLength = 0;
        actualLineSeparator = CHUNK_SEPARATOR;
    }

    // Logical correction: Calculate the expected encoded length using the
    // determined actual chunking parameters. This ensures consistency.
    long len = getEncodeLength(binaryData, actualLineLength, actualLineSeparator);

    if (len > maxResultSize) {
        // Corrected typo: "maxium" to "maximum"
        throw new IllegalArgumentException("Input array too big, the output array would be bigger (" +
            len +
            ") than the specified maximum size of " +
            maxResultSize);
    }

    // Logical correction: Create the Base64 instance using the explicit constructor
    // that allows setting lineLength, lineSeparator, and urlSafe consistently.
    // This ensures chunking is applied correctly when isChunked is true, regardless of urlSafe.
    Base64 b64 = new Base64(actualLineLength, actualLineSeparator, urlSafe);
    return b64.encode(binaryData);
}

@Override
public Iterator<CSVRecord> iterator() {
    return new Iterator<CSVRecord>() {
        // 'current' holds the next CSVRecord to be returned by the next() method.
        // It's used for the pre-fetching mechanism in hasNext().
        private CSVRecord current;

        /**
         * Internal helper method to fetch the next CSV record from the parser.
         * It wraps any checked IOException from the underlying parser into an unchecked IllegalStateException.
         *
         * @return The next CSVRecord, or {@code null} if no more records are available from the parser.
         * @throws IllegalStateException if an IOException occurs during the record reading process.
         */
        private CSVRecord getNextRecord() {
            try {
                return CSVParser.this.nextRecord();
            } catch (final IOException e) {
                // Wrap the checked IOException into an unchecked IllegalStateException,
                // as Iterator methods cannot declare checked exceptions.
                throw new IllegalStateException(
                        e.getClass().getSimpleName() + " encountered while reading next CSV record: " + e.getMessage(), e);
            }
        }

        /**
         * Checks if there are more CSV records available for iteration.
         * This method pre-fetches the next record if it hasn't been done already.
         *
         * @return {@code true} if there is at least one more record, {@code false} otherwise.
         * @throws IllegalStateException if the underlying parser encounters an I/O error during pre-fetching.
         */
        @Override
        public boolean hasNext() {
            // If the underlying CSVParser has been closed, no more records can be read.
            if (CSVParser.this.isClosed()) {
                return false;
            }
            // If 'current' is null, it means we need to pre-fetch the next record.
            // This happens on the first call to hasNext(), or after a next() call.
            if (this.current == null) {
                this.current = this.getNextRecord();
            }
            // Return true if a record was successfully pre-fetched (i.e., not end of stream).
            return this.current != null;
        }

        /**
         * Returns the next CSV record in the iteration.
         *
         * @return The next {@link CSVRecord}.
         * @throws NoSuchElementException if the iteration has no more elements,
         *                                or if the underlying {@link CSVParser} has been closed.
         * @throws IllegalStateException if the underlying parser encounters an I/O error during record reading.
         */
        @Override
        public CSVRecord next() {
            // Ensure the parser is not closed before attempting to retrieve a record.
            if (CSVParser.this.isClosed()) {
                throw new NoSuchElementException("CSVParser has been closed, no more records available.");
            }

            CSVRecord nextRecordToReturn = this.current;
            this.current = null; // Mark the pre-fetched record as consumed.

            // If 'nextRecordToReturn' is null, it implies hasNext() was not called,
            // or it returned false, or the previous next() consumed the last record.
            // In this case, attempt to fetch the record directly.
            if (nextRecordToReturn == null) {
                nextRecordToReturn = this.getNextRecord();
                if (nextRecordToReturn == null) {
                    // If still null, it means we've reached the end of the stream.
                    throw new NoSuchElementException("No more CSV records available.");
                }
            }

            return nextRecordToReturn;
        }

        /**
         * This operation is not supported for a read-only CSV parser.
         *
         * @throws UnsupportedOperationException always.
         */
        @Override
        public void remove() {
            throw new UnsupportedOperationException("remove() is not supported by this CSVRecord iterator.");
        }
    };
}

