@Override public void skipValue() throws IOException {
    JsonToken token = peek();

    switch (token) {
        case BEGIN_ARRAY:
            // Consume the opening bracket
            beginArray();
            // Recursively skip all elements until the end of the array
            while (hasNext()) {
                skipValue();
            }
            // Consume the closing bracket
            endArray();
            break;
        case BEGIN_OBJECT:
            // Consume the opening brace
            beginObject();
            // Recursively skip all name-value pairs until the end of the object
            while (hasNext()) {
                // First, consume the name
                nextName();
                // Then, recursively skip the value associated with that name
                skipValue();
            }
            // Consume the closing brace
            endObject();
            break;
        case NAME:
            // If the current token is a name, consume the name first
            nextName();
            // Then, recursively skip the value associated with that name
            skipValue();
            break;
        case STRING:
            // For simple values, call the corresponding nextXxx() method
            // These methods internally handle popping the value and updating path tracking.
            nextString();
            break;
        case NUMBER:
            nextDouble(); // nextDouble() consumes the number, handles int/long too
            break;
        case BOOLEAN:
            nextBoolean();
            break;
        case NULL:
            nextNull();
            break;
        case END_DOCUMENT:
            // If we are at the end of the document, there's nothing to skip.
            // This indicates an attempt to skip beyond the document, which is an error.
            throw new IllegalStateException("Expected a value but was " + token + " at path " + getPath());
        case END_ARRAY:
        case END_OBJECT:
            // These tokens should not be skipped directly as values.
            // They are consumed by endArray() and endObject() respectively.
            // If peek() returns these, it means we are at the end of a container,
            // and skipValue() should not be called on them directly.
            throw new IllegalStateException("Expected a value but was " + token + " at path " + getPath());
        default:
            // This case should ideally not be reached if all JsonToken types are covered.
            // If it is, it indicates an unexpected or unsupported state.
            throw new IllegalStateException("Unexpected token " + token + " at path " + getPath());
    }
}

public static WildcardType subtypeOf(Type bound) {
    // Robustness: Ensure the bound is not null.
    // A null Type is not a valid bound for a wildcard.
    if (bound == null) {
        throw new NullPointerException("Bound for a wildcard type cannot be null.");
    }

    // Robustness: Ensure the bound is not a primitive type.
    // According to the Java Language Specification, wildcard bounds must be reference types.
    // The $Gson$Types utility class provides a helper for this validation.
    checkNotPrimitive(bound);

    // Create an array containing the single upper bound.
    // This represents the 'T' in '? extends T'.
    Type[] upperBounds = new Type[] { bound };

    // For an upper-bounded wildcard ('? extends T'), there are no lower bounds.
    // Use the predefined empty array for lower bounds, which is a static final field.
    return new WildcardTypeImpl(upperBounds, EMPTY_TYPE_ARRAY);
}

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
        throw new NullPointerException("Bound type cannot be null for a wildcard lower bound.");
    }
    Type[] lowerBounds = new Type[] { bound };
    return new WildcardTypeImpl(new Type[] { Object.class }, lowerBounds);
}

