public int nextInt() throws IOException {
    int p = peeked;
    if (p == PEEKED_NONE) {
      p = doPeek();
    }

    int result;
    if (p == PEEKED_LONG) {
      result = (int) peekedLong;
      if (peekedLong != result) { // Make sure no precision was lost casting to 'int'.
        throw new NumberFormatException("Expected an int but was " + peekedLong
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
      }
      peeked = PEEKED_NONE;
      pathIndices[stackSize - 1]++;
      return result;
    }

    // If the token is an unquoted number, extract it into peekedString.
    if (p == PEEKED_NUMBER) {
      peekedString = new String(buffer, pos, peekedNumberLength);
      pos += peekedNumberLength;
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
      peekedString = nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
    } else if (p != PEEKED_BUFFERED) { // If it's not PEEKED_LONG, PEEKED_NUMBER, quoted, or already buffered
      throw new IllegalStateException("Expected an int but was " + peek()
          + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }
    // At this point, if we are not PEEKED_LONG, then peekedString should contain the string
    // representation of the number (either newly extracted or already buffered).
    // Set peeked to PEEKED_BUFFERED to reflect that peekedString holds the value,
    // consistent with the original code's flow before parsing.
    peeked = PEEKED_BUFFERED;

    // Now, attempt to parse peekedString as an int first, then as a double if int fails.
    try {
      result = Integer.parseInt(peekedString);
      // If successful, consume the token and return.
      peekedString = null; // Clear the buffered string.
      peeked = PEEKED_NONE;
      pathIndices[stackSize - 1]++;
      return result;
    } catch (NumberFormatException e) {
      // If Integer.parseInt fails, try parsing as a double and then casting to int.
      // This handles cases like "123.0" or numbers that might fit in double but not int directly.
      try {
        double asDouble = Double.parseDouble(peekedString);
        result = (int) asDouble;
        if (result != asDouble) { // Make sure no precision was lost casting to 'int'.
          // Precision was lost (e.g., "123.45" or a number too large for int).
          throw new NumberFormatException("Expected an int but was " + peekedString
              + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        // If successful, consume the token and return.
        peekedString = null; // Clear the buffered string.
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
      } catch (NumberFormatException e2) {
        // If even Double.parseDouble fails, then it's not a valid number format at all.
        // Ensure the token is consumed even on final parsing failure for robustness.
        peekedString = null; // Clear the buffered string.
        peeked = PEEKED_NONE; // Mark as consumed.
        pathIndices[stackSize - 1]++; // Increment path index.
        throw new NumberFormatException("Expected an int but was " + peekedString
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath() + ". Original error: " + e2.getMessage());
      }
    }
  }

