public static UnsafeAllocator create() {
        // Collect all exceptions encountered during the discovery phase for better diagnostics.
        List<Throwable> suppressedExceptions = new ArrayList<>();

        // Attempt 1: Standard JVM (sun.misc.Unsafe)
        try {
            Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
            Field f = unsafeClass.getDeclaredField("theUnsafe");
            f.setAccessible(true); // Bypass access checks for the private field
            final Object unsafe = f.get(null); // Get the singleton Unsafe instance
            final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using sun.misc.Unsafe.");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    return (T) allocateInstance.invoke(unsafe, c);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using sun.misc.Unsafe.", e);
            suppressedExceptions.add(e);
        }

        // Attempt 2: Dalvik/Android (post-Gingerbread, ObjectStreamClass)
        try {
            Method getConstructorId = ObjectStreamClass.class
                .getDeclaredMethod("getConstructorId", Class.class);
            getConstructorId.setAccessible(true); // Bypass access checks
            // Obtain a constructor ID for Object.class, which is a known hack for constructor-less allocation on Dalvik.
            final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
            final Method newInstance = ObjectStreamClass.class
                .getDeclaredMethod("newInstance", Class.class, int.class);
            newInstance.setAccessible(true); // Bypass access checks
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using ObjectStreamClass (Dalvik post-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    return (T) newInstance.invoke(null, c, constructorId);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using ObjectStreamClass (Dalvik post-Gingerbread).", e);
            suppressedExceptions.add(e);
        }

        // Attempt 3: Dalvik/Android (pre-Gingerbread, ObjectInputStream)
        try {
            final Method newInstance = ObjectInputStream.class
                .getDeclaredMethod("newInstance", Class.class, Class.class);
            newInstance.setAccessible(true); // Bypass access checks
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using ObjectInputStream (Dalvik pre-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    // Pass Object.class as the constructorClass, a known hack for constructor-less allocation.
                    return (T) newInstance.invoke(null, c, Object.class);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using ObjectInputStream (Dalvik pre-Gingerbread).", e);
            suppressedExceptions.add(e);
        }

        // Fallback: No suitable unsafe allocator found.
        logger.log(Level.WARNING, "No suitable unsafe allocator mechanism found on this platform. Object allocation without constructor will fail.");
        return new UnsafeAllocator() {
            @Override
            public <T> T newInstance(Class<T> c) {
                if (c == null) {
                    throw new IllegalArgumentException("Class to instantiate cannot be null.");
                }
                UnsupportedOperationException uoe = new UnsupportedOperationException(
                    "Cannot allocate " + c.getName() + " without calling a constructor. No suitable unsafe allocator found on this platform."
                );
                // Add all collected exceptions as suppressed exceptions for better diagnostics.
                for (Throwable suppressed : suppressedExceptions) {
                    uoe.addSuppressed(suppressed);
                }
                throw uoe;
            }
        };
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count == 0) {
            return "";
        }
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (random == null) {
            throw new NullPointerException("The 'random' generator must not be null.");
        }
        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The chars array must not be empty.");
        }

        // Determine effective start and end based on defaults if (0,0) is passed
        int actualStart = start;
        int actualEnd = end;

        if (actualStart == 0 && actualEnd == 0) {
            if (chars != null) {
                actualEnd = chars.length;
            } else {
                if (!letters && !numbers) {
                    actualStart = Character.MIN_VALUE; // 0
                    actualEnd = Character.MAX_VALUE + 1; // 65536 (exclusive), covers all BMP chars
                } else {
                    actualStart = ' '; // ASCII 32
                    actualEnd = 'z' + 1; // ASCII 123 (exclusive), covers ' ' through 'z'
                }
            }
        }

        // Validate actualStart and actualEnd based on whether chars array is used
        if (chars != null) {
            if (actualStart < 0 || actualStart >= chars.length) {
                throw new IllegalArgumentException("The 'start' parameter (" + actualStart + ") is out of bounds for the 'chars' array (length " + chars.length + ").");
            }
            if (actualEnd < 0 || actualEnd > chars.length) {
                throw new IllegalArgumentException("The 'end' parameter (" + actualEnd + ") is out of bounds for the 'chars' array (length " + chars.length + ").");
            }
        } else { // chars == null, so start/end are character code points
            if (actualStart < Character.MIN_VALUE || actualStart > Character.MAX_VALUE) {
                throw new IllegalArgumentException("The 'start' parameter (" + actualStart + ") is out of valid char code point range (0-" + Character.MAX_VALUE + ").");
            }
            // actualEnd can be Character.MAX_VALUE + 1 as it's exclusive
            if (actualEnd < Character.MIN_VALUE || actualEnd > Character.MAX_VALUE + 1) {
                throw new IllegalArgumentException("The 'end' parameter (" + actualEnd + ") is out of valid char code point range (0-" + (Character.MAX_VALUE + 1) + ").");
            }
        }

        if (actualStart >= actualEnd) {
            throw new IllegalArgumentException("The 'start' parameter (" + actualStart + ") must be strictly less than the 'end' parameter (" + actualEnd + ").");
        }

        StringBuilder buffer = new StringBuilder(count);
        int gap = actualEnd - actualStart;

        // Loop to generate 'count' characters
        for (int i = 0; i < count; i++) {
            char ch;
            boolean charFound = false;
            int attempts = 0; // Safeguard against infinite loops for a single character

            // Inner loop to find a character that matches all criteria
            while (!charFound) {
                if (attempts++ > 1000) { // Arbitrary limit to prevent infinite loops
                    throw new IllegalArgumentException("No character found for the specified criteria after " + attempts + " attempts. " +
                                                       "Consider adjusting 'start', 'end', 'letters', 'numbers', or 'chars' parameters.");
                }

                if (chars == null) {
                    // Generate a character code point
                    ch = (char) (random.nextInt(gap) + actualStart);
                    // Exclude surrogate characters (U+D800 to U+DFFF) if generating from code points
                    // This ensures valid BMP characters are always generated.
                    if (Character.isSurrogate(ch)) {
                        continue; // Re-roll if it's a surrogate
                    }
                } else {
                    // Pick a character from the provided array
                    ch = chars[random.nextInt(gap) + actualStart];
                    // If a custom chars array is provided, we assume the user is responsible
                    // for its content and handling of potential surrogates within it.
                }

                // Apply filtering based on letters and numbers flags
                if (letters && Character.isLetter(ch)
                        || numbers && Character.isDigit(ch)
                        || (!letters && !numbers)) { // If neither letters nor numbers are requested, accept any valid char
                    buffer.append(ch);
                    charFound = true;
                }
                // If charFound is still false, the inner while loop continues (re-rolls)
            }
        }
        return buffer.toString();
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        // Robustness: random null check
        Objects.requireNonNull(random, "random cannot be null");

        // Input validation for count
        if (count == 0) {
            return "";
        } else if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }

        // Robustness: chars array validation
        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The 'chars' array must not be empty if provided.");
        }

        // Default start and end values if both are 0
        if (start == 0 && end == 0) {
            if (chars != null) {
                // Logical Mistake 3 & Robustness: If chars array is provided, default range is its full length (indices)
                start = 0;
                end = chars.length;
            } else if (!letters && !numbers) {
                // Logical Mistake 1: Cap end at Character.MAX_VALUE for character value range
                start = Character.MIN_VALUE; // 0
                end = Character.MAX_VALUE;   // 65535
            } else {
                // Default for letters/numbers, printable ASCII range
                start = ' '; // 32
                end = 'z' + 1; // 123
            }
        }

        // Robustness: Validate start and end values
        if (start < 0) {
            throw new IllegalArgumentException("The 'start' parameter must be non-negative.");
        }
        if (end < start) {
            throw new IllegalArgumentException("The 'end' parameter must be greater than or equal to 'start'.");
        }

        int gap;
        if (chars == null) {
            // For character value range, ensure end doesn't exceed char max
            if (end > Character.MAX_VALUE) {
                end = Character.MAX_VALUE;
            }
            gap = end - start;
        } else {
            // For chars array indices, ensure end doesn't exceed array length
            if (end > chars.length) {
                throw new IllegalArgumentException("The 'end' parameter (" + end + ") must not exceed the 'chars' array length (" + chars.length + ").");
            }
            gap = end - start;
        }

        // Robustness: Ensure a valid range for random character selection
        if (gap <= 0) { // This covers start == end as well
            throw new IllegalArgumentException("The character range (end - start) must be positive.");
        }

        char[] buffer = new char[count];
        int currentCount = 0; // Tracks how many characters have been placed in the buffer (from left to right)

        while (currentCount < count) {
            char ch;
            if (chars == null) {
                ch = (char) (random.nextInt(gap) + start);
            } else {
                // charIndex will be in [start, end) due to prior validation
                int charIndex = random.nextInt(gap) + start;
                ch = chars[charIndex];
            }

            // Filtering logic
            // Accept if: (letters is true AND ch is a letter) OR (numbers is true AND ch is a digit) OR (both letters and numbers are false)
            if ((letters && Character.isLetter(ch))
                    || (numbers && Character.isDigit(ch))
                    || (!letters && !numbers)) {

                // Surrogate pair handling
                if (Character.isLowSurrogate(ch)) { // U+DC00 to U+DFFF
                    // Logical Mistake 2: Ensure enough space for a full pair
                    if (currentCount + 1 >= count) { 
                        continue; // Not enough space, skip this character and retry for the same position
                    }
                    // Place high surrogate first, then low surrogate
                    // Using random.nextInt(128) to match the original code's likely intent for limited surrogate range
                    buffer[currentCount++] = (char) (0xD800 + random.nextInt(128)); // Random High Surrogate (U+D800 to U+D87F)
                    buffer[currentCount++] = ch; // Place the chosen low surrogate
                } else if (Character.isHighSurrogate(ch)) { // U+D800 to U+DFFF
                    // Check for private use high surrogates (U+DB80 to U+DBFF)
                    if (ch >= 0xDB80 && ch <= 0xDBFF) { 
                        continue; // Skip private use high surrogates, retry for the same position
                    }

                    // Logical Mistake 2: Ensure enough space for a full pair
                    if (currentCount + 1 >= count) { 
                        continue; // Not enough space, skip this character and retry for the same position
                    }
                    // Place high surrogate first, then low surrogate
                    // Using random.nextInt(128) to match the original code's likely intent for limited surrogate range
                    buffer[currentCount++] = ch; // Place the chosen high surrogate
                    buffer[currentCount++] = (char) (0xDC00 + random.nextInt(128)); // Random Low Surrogate (U+DC00 to U+DC7F)
                } else {
                    // Regular character
                    buffer[currentCount++] = ch;
                }
            } else {
                // Character did not pass filter, retry for the same position
                continue;
            }
        }
        return new String(buffer);
    }

public static boolean equals(final CharSequence cs1, final CharSequence cs2) {
    // Handle identical references (including both null)
    if (cs1 == cs2) {
        return true;
    }
    // Handle cases where one is null and the other is not
    if (cs1 == null || cs2 == null) {
        return false;
    }

    // At this point, both cs1 and cs2 are guaranteed to be non-null.

    // Compare lengths first for efficiency. If lengths differ, content cannot be equal.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // Optimization: If both are String instances, use String.equals() for potentially better performance.
    // String.equals() is known to perform content-based comparison.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // For all other CharSequence implementations (e.g., StringBuilder, StringBuffer, custom CharSequence),
    // perform a character-by-character comparison to ensure content equality.
    for (int i = 0; i < cs1.length(); i++) {
        if (cs1.charAt(i) != cs2.charAt(i)) {
            return false; // Characters differ at this position
        }
    }

    // All characters matched
    return true;
}

@Override
