        if (input == null) {
            // According to CharSequenceTranslator contract, returning 0 for null input is acceptable
            // as it signifies no translation occurred.
            return 0;
        }
        if (out == null) {
            // A null Writer is a critical error, as output cannot be written.
            throw new IllegalArgumentException("Output Writer cannot be null.");
        }

