            // This loop now correctly handles entities without a trailing semicolon,
            // stopping at the first non-numeric/non-hex character or the end of the sequence.
            while (end < seqEnd) {
                char c = input.charAt(end);
                if (isHex) {
                    // Check if character is a valid hexadecimal digit
                    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                        break; // Not a hex digit, so the numeric part ends here
                    }
                } else {
                    // Check if character is a valid decimal digit
                    if (!(c >= '0' && c <= '9')) {
                        break; // Not a decimal digit, so the numeric part ends here
                    }
                }
                end++;
            }

            // Robustness: Check if any digits were found between 'start' and 'end'.
            // E.g., for "&#;" or "&#x;", 'start' and 'end' would be the same.
            if (end == start) {
                return 0; // No digits found after "&#" or "&#x", so not a valid numeric entity.
            }

            // Extract the numeric part of the entity
            String entityStr = input.subSequence(start, end).toString();

            int entityValue;
            try {
                if (isHex) {
                    entityValue = Integer.parseInt(entityStr, 16);
                } else {
                    entityValue = Integer.parseInt(entityStr, 10);
                }
            } catch (NumberFormatException nfe) {
                // Malformed numeric entity (e.g., "&#123G;" or "&#xFGZ;").
                // Return 0 to indicate no translation occurred at this point.
                return 0;
            }

            // Robustness: Validate the parsed entity value as a valid Unicode code point.
            // Character.toChars can throw IllegalArgumentException for values outside this range.
            if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
                // Invalid Unicode code point, treat as no translation.
                return 0;
            }

            // Write the character(s) to the output writer
            if (entityValue > 0xFFFF) { // Code point requires a surrogate pair
                char[] chrs = Character.toChars(entityValue);
                out.write(chrs[0]);
                out.write(chrs[1]);
            } else { // Code point is a single character
                out.write(entityValue);
            }

            // Calculate the total number of characters consumed from the input sequence.
            int charsConsumed = 2; // For "&#"
            if (isHex) {
                charsConsumed += 1; // For 'x' or 'X'
            }
            charsConsumed += (end - start); // For the numeric part (e.g., "123" or "7B")

            // Check for and consume an optional semicolon.
            // This handles both "&#123;" and "&#123" forms.
            if (end < seqEnd && input.charAt(end) == ';') {
                charsConsumed += 1; // For ';'
            }

            return charsConsumed;
        }
        return 0; // Not a numeric entity, no translation occurred.
    }

public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY; // Assuming EMPTY is defined as ""
    }

    // Validate indices against array bounds
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
    }
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY; // Handles cases where startIndex >= endIndex
    }

    // Improved StringBuilder capacity estimation
    // A reasonable heuristic: assume an average string length of 16 characters per item.
    // This avoids accessing array elements for length estimation before they are processed.
    int capacity = noOfItems * 16;
    if (noOfItems > 1) {
        capacity += separator.length() * (noOfItems - 1);
    }
    StringBuilder buf = new StringBuilder(capacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}

public static boolean isSameLocalTime(Calendar cal1, Calendar cal2) {
    if (cal1 == null || cal2 == null) {
        throw new IllegalArgumentException("The date must not be null");
    }
    // Compare only the time-of-day components, ignoring date and calendar type.
    // Use HOUR_OF_DAY for unambiguous hour comparison (0-23).
    return (cal1.get(Calendar.MILLISECOND) == cal2.get(Calendar.MILLISECOND) &&
            cal1.get(Calendar.SECOND) == cal2.get(Calendar.SECOND) &&
            cal1.get(Calendar.MINUTE) == cal2.get(Calendar.MINUTE) &&
            cal1.get(Calendar.HOUR_OF_DAY) == cal2.get(Calendar.HOUR_OF_DAY));
}

public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int sz = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSigns = false; // True if a sign is allowed (e.g., after 'e' or at the beginning)
        boolean foundDigit = false; // True if at least one digit has been found

        // Determine the starting index after an optional leading sign
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') { // Corrected: Handle both '-' and '+'
            start = 1;
        }

        // If the string is just a sign ("+" or "-"), it's not a number
        if (start == sz) {
            return false;
        }

        // Handle hexadecimal numbers (e.g., "0x1a", "-0xAF")
        // Need at least "0x" or "-0x" + one hex digit
        if (sz > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int i = start + 2;
            if (i == sz) {
                return false; // str == "0x" or "-0x"
            }
            // checking hex (it can't be anything else)
            for (; i < chars.length; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9')
                    || (chars[i] >= 'a' && chars[i] <= 'f')
                    || (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // Main loop for decimal, float, double, long
        // Loop through characters, stopping before the last one, unless it's a sign after 'E'
        // The loop processes characters from `start` up to `chars.length - 2`.
        // The character at `chars.length - 1` (the actual last character) is handled after the loop,
        // UNLESS it's a sign after 'E' and no digit has been found yet (e.g., "1E+").
        int loopEnd = chars.length - 1; // Index of the last character
        int i = start;

        while (i < loopEnd || (i == loopEnd && allowSigns && !foundDigit)) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSigns = false; // No sign allowed after a digit (unless it's an exponent sign)

            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // two decimal points or dec in exponent
                    return false;
                }
                hasDecPoint = true;
                // foundDigit is NOT set here. This means ".5" will not have foundDigit=true
                // until the '5' is processed, which is handled in the post-loop block.

            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    // two E's
                    return false;
                }
                if (!foundDigit) {
                    // Must have at least one digit before 'E' (e.g., "1E", "1.2E")
                    return false;
                }
                hasExp = true;
                allowSigns = true; // A sign is allowed immediately after 'E'
                // foundDigit is NOT reset here. It will be reset if a sign follows 'E'.

            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSigns) {
                    // Sign only allowed at start or after 'E'
                    return false;
                }
                allowSigns = false; // Only one sign allowed in this context
                foundDigit = false; // We need a digit after the sign (e.g., "1E+5", not "1E+")
            } else {
                return false; // Invalid character
            }
            i++;
        }

        // Handle the last character (if any)
        // `i` is now `chars.length - 1` (the actual last character) or `chars.length`
        if (i < chars.length) { // This means `i` is `chars.length - 1`
            if (chars[i] >= '0' && chars[i] <= '9') {
                // No type qualifier, OK (e.g., "123", "1.23")
                // Corrected: Must have found a digit *before* this last digit,
                // or this last digit is the *only* digit and it's not part of ".5" type cases.
                // The `foundDigit` flag correctly tracks if *any* digit was found.
                // For ".5", `foundDigit` is false when '5' is processed.
                return foundDigit; // Corrected: ".5" will now return false.
            }
            if (chars[i] == 'e' || chars[i] == 'E') {
                // Can't have an E at the last byte (e.g., "1E")
                return false;
            }
            if (chars[i] == '.') {
                // Logical Mistake 1: Trailing decimal point like "1."
                if (hasDecPoint || hasExp) {
                    // two decimal points or dec in exponent
                    return false;
                }
                // If we reach here, it's a single trailing decimal point (e.g., "1.").
                // This should be false according to createNumber.
                return false; // Corrected: "1." should not be a number.
            }
            if (!allowSigns
                && (chars[i] == 'd'
                    || chars[i] == 'D'
                    || chars[i] == 'f'
                    || chars[i] == 'F')) {
                // Type qualifier for double/float (e.g., "1.2f", "1d")
                // `!allowSigns` ensures it's not like "1E+f"
                return foundDigit; // Must have found a digit before the qualifier
            }
            if (chars[i] == 'l' || chars[i] == 'L') {
                // Type qualifier for long (e.g., "123L")
                // Logical Mistake 2: Disallow with decimal point.
                return foundDigit && !hasExp && !hasDecPoint; // Corrected: Must not have exponent or decimal point
            }
            // last character is illegal
            return false;
        }

        // If `i == chars.length`, it means the loop processed all characters.
        // This final check handles cases like "123", "1.23", "1E2".
        // `allowSigns` is true iff the val ends in 'E' or 'E+' or 'E-' (and no digit followed).
        // `foundDigit` is to make sure weird stuff like '.' and '1E-' doesn't pass.
        return !allowSigns && foundDigit;
    }

public String format(Date date) {
    // Robustness: Validate the input 'date' parameter to prevent NullPointerException.
    // If 'date' is null, throw an IllegalArgumentException with a descriptive message.
    if (date == null) {
        throw new IllegalArgumentException("Date must not be null.");
    }

    // Logical: Create a new Calendar instance, specifically a GregorianCalendar,
    // initialized with the time zone configured for this FastDateFormat instance (mTimeZone).
    // This ensures that date/time calculations and formatting are performed in the correct time zone.
    Calendar c = new GregorianCalendar(mTimeZone);

    // Logical: Set the time of the Calendar instance to the provided Date object.
    // This transfers the specific instant in time from the Date to the Calendar for processing.
    c.setTime(date);

    // Logical: Apply the internal formatting rules to the Calendar instance.
    // A new StringBuffer is created with an estimated maximum length (mMaxLengthEstimate)
    // to optimize string building performance by reducing reallocations.
    // The applyRules method (a protected helper) populates this StringBuffer.
    // Finally, the content of the StringBuffer is converted to a String and returned.
    return applyRules(c, new StringBuffer(mMaxLengthEstimate)).toString();
}

@Override
public int translate(CharSequence input, int index, Writer out) throws IOException {
    // Robustness: Null checks for input and output writer
    if (out == null) {
        throw new NullPointerException("The Writer must not be null.");
    }
    if (input == null) {
        return 0; // As per CharSequenceTranslator contract, null input means no translation.
    }

    // Robustness: Check if there's enough characters for at least "&#"
    // An entity must be at least 4 characters long (e.g., "&#0;")
    if (index < 0 || index >= input.length() - 2) { // Need at least input[index], input[index+1], input[index+2]
        return 0;
    }

    // Check for the start of a numeric entity: "&#"
    if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
        int start = index + 2; // Position after "&#"
        boolean isHex = false;

        // Robustness: Check if there's at least one character after "&#"
        // This character could be 'x'/'X' or the first digit.
        if (start >= input.length()) {
            return 0; // Malformed entity: "&#" at end of string, no content or semicolon.
        }

        char firstCharAfterHash = input.charAt(start);
        if (firstCharAfterHash == 'x' || firstCharAfterHash == 'X') {
            // It's a hexadecimal entity (e.g., "&#x7B;")
            start++; // Move past 'x' or 'X'
            isHex = true;

            // Robustness: Check if there's at least one character after "&#x"
            // This character must be a digit or the semicolon.
            if (start >= input.length()) {
                return 0; // Malformed entity: "&#x" at end of string, no content or semicolon.
            }
        }

        int end = start;
        // Robustness: Find the closing ';' while staying within bounds
        while (end < input.length() && input.charAt(end) != ';') {
            end++;
        }

        // Robustness: If ';' was not found, it's a malformed entity
        if (end == input.length()) {
            return 0;
        }

        // Robustness: Check if there's actual content between start and end (e.g., "&#;" or "&#x;")
        if (start == end) {
            return 0; // Empty entity, e.g., "&#;" or "&#x;"
        }

        int entityValue;
        try {
            String numericPart = input.subSequence(start, end).toString();
            if (isHex) {
                entityValue = Integer.parseInt(numericPart, 16);
            } else {
                entityValue = Integer.parseInt(numericPart, 10);
            }
        } catch (NumberFormatException nfe) {
            // Robustness: If the numeric part is not a valid number, it's not a valid entity
            return 0;
        }

        // Robustness: Check for valid Unicode code point range
        // HTML/XML entities are typically within valid Unicode range (0 to 0x10FFFF).
        if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
             return 0; // Not a valid Unicode code point, treat as malformed
        }

        out.write(entityValue); // Write the unescaped character

        // Calculate the number of characters consumed from the input.
        // This includes the initial '&', '#', optional 'x', the numeric part, and the final ';'.
        // The length is (position of ';') - (start of '&') + 1.
        return (end - index) + 1;
    }
    return 0; // Not a numeric entity, return 0
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) { // Using assumed isBlank
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // --- Hexadecimal Number Handling ---
        // Need to deal with all possible hex prefixes here
        // {"0x", "0X", "-0x", "-0X", "#", "-#"}
        String hexValue = str;
        int sign = 1;
        if (str.startsWith("-")) {
            sign = -1;
            hexValue = str.substring(1);
        }

        int hexPrefixLen = 0;
        if (hexValue.startsWith("0x") || hexValue.startsWith("0X")) {
            hexPrefixLen = 2;
        } else if (hexValue.startsWith("#")) {
            hexPrefixLen = 1;
        }

        if (hexPrefixLen > 0) { // It's a hex number
            final String actualHexDigits = hexValue.substring(hexPrefixLen);
            if (actualHexDigits.isEmpty()) {
                throw new NumberFormatException(str + " is not a valid hex number: empty digits after prefix.");
            }
            final int hexDigitsCount = actualHexDigits.length();

            // Integer.decode and Long.decode handle prefixes and signs correctly.
            // BigInteger needs the prefix and sign handled explicitly.
            if (hexDigitsCount > 16) { // too many for Long
                BigInteger bi = new BigInteger(actualHexDigits, 16);
                return sign == -1 ? bi.negate() : bi;
            }
            if (hexDigitsCount > 8) { // too many for an int
                return createLong(str); // createLong (via Long.decode) handles original string
            }
            return createInteger(str); // createInteger (via Integer.decode) handles original string
        }

        // --- Non-Hexadecimal Number Handling ---
        final char lastChar = str.charAt(str.length() - 1);
        String numericStr = str;
        boolean hasSuffix = false;

        // Check for type suffixes
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            switch (lastChar) {
                case 'l':
                case 'L':
                case 'f':
                case 'F':
                case 'd':
                case 'D':
                    hasSuffix = true;
                    numericStr = str.substring(0, str.length() - 1);
                    break;
                default:
                    // If it's not a recognized suffix, it's an invalid number
                    throw new NumberFormatException(str + " is not a valid number: unrecognized suffix '" + lastChar + "'.");
            }
        }

        // Parse numericStr into mantissa, decimal part, and exponent part
        final int decPos = numericStr.indexOf('.');
        int expPos = -1;
        int expPosE = numericStr.indexOf('e');
        int expPosUpperE = numericStr.indexOf('E');

        if (expPosE > -1) {
            expPos = expPosE;
        }
        if (expPosUpperE > -1) {
            if (expPos == -1 || expPosUpperE < expPos) { // Take the earlier one
                expPos = expPosUpperE;
            }
        }

        // --- Robustness Checks for malformed numbers ---
        // Check for multiple decimal points
        if (decPos > -1 && numericStr.indexOf('.', decPos + 1) > -1) {
            throw new NumberFormatException(str + " is not a valid number: multiple decimal points.");
        }
        // Check for multiple exponent indicators
        if (expPos > -1) {
            if ((expPosE > -1 && numericStr.indexOf('e', expPosE + 1) > -1) ||
                (expPosUpperE > -1 && numericStr.indexOf('E', expPosUpperE + 1) > -1)) {
                throw new NumberFormatException(str + " is not a valid number: multiple exponent indicators.");
            }
        }
        // Check for exponent before decimal
        if (decPos > -1 && expPos > -1 && expPos < decPos) {
            throw new NumberFormatException(str + " is not a valid number: exponent before decimal point.");
        }

        String mant;
        String dec;
        String exp;

        if (decPos > -1) { // Has decimal point
            if (expPos > -1) { // Has exponent
                mant = numericStr.substring(0, decPos);
                dec = numericStr.substring(decPos + 1, expPos);
                exp = numericStr.substring(expPos + 1);
            } else { // No exponent
                mant = numericStr.substring(0, decPos);
                dec = numericStr.substring(decPos + 1);
                exp = null;
            }
        } else { // No decimal point
            if (expPos > -1) { // Has exponent
                mant = numericStr.substring(0, expPos);
                dec = null;
                exp = numericStr.substring(expPos + 1);
            } else { // No decimal, no exponent
                mant = numericStr;
                dec = null;
                exp = null;
            }
        }

        // Robustness: Check for empty parts that are typically invalid
        if (exp != null && exp.isEmpty()) {
            throw new NumberFormatException(str + " is not a valid number: empty exponent part.");
        }
        // e.g., "e123" or "+e123" -> mant="", dec=null, exp="123"
        // This is invalid unless it's a decimal like ".123" (mant is empty, dec is not null)
        if (mant.isEmpty() && dec == null && exp != null) {
            // Check if it's just a sign followed by exponent, e.g., "+e123"
            if (numericStr.length() > 0 && (numericStr.charAt(0) == '+' || numericStr.charAt(0) == '-')) {
                throw new NumberFormatException(str + " is not a valid number: empty mantissa before exponent.");
            }
        }

        final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

        // --- Handle Type-Hinted Numbers (Suffixes) ---
        if (hasSuffix) {
            switch (lastChar) {
                case 'l':
                case 'L':
                    if (dec != null || exp != null) {
                        throw new NumberFormatException(str + " is not a valid Long: cannot contain decimal or exponent.");
                    }
                    try {
                        return createLong(numericStr);
                    } catch (final NumberFormatException nfe) { // NOPMD
                        // Too big for a long, try BigInteger
                    }
                    return createBigInteger(numericStr);

                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numericStr);
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            // If it's too big for a float or the float value = 0 and the string
                            // has non-zeros in it, then float does not have the precision we want
                            return f;
                        }
                    } catch (final NumberFormatException nfe) { // NOPMD
                        // ignore the bad number, fall through to double/bigdecimal
                    }
                    // $FALL-THROUGH$
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numericStr);
                        // FIX: Changed d.floatValue() to d.doubleValue()
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) { // NOPMD
                        // ignore the bad number, fall through to bigdecimal
                    }
                    try {
                        return createBigDecimal(numericStr);
                    } catch (final NumberFormatException e) { // NOPMD
                        // ignore the bad number, will be caught by outer exception if no other type works
                    }
                    // If 'f'/'F' or 'd'/'D' parsing failed completely, throw exception
                    throw new NumberFormatException(str + " is not a valid floating point number.");
            }
        }

        // --- Handle No Type Hint (Default Behavior) ---
        // User doesn't have a preference on the return type, so let's start
        // small and go from there...
        if (dec == null && exp == null) { // no decimal point and no exponent
            // Must be an Integer, Long, BigInteger
            try {
                return createInteger(numericStr);
            } catch (final NumberFormatException nfe) { // NOPMD
                // ignore the bad number, try Long
            }
            try {
                return createLong(numericStr);
            } catch (final NumberFormatException nfe) { // NOPMD
                // ignore the bad number, try BigInteger
            }
            return createBigInteger(numericStr);
        }

        // Must be a Float, Double, BigDecimal
        try {
            final Float f = createFloat(numericStr);
            if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                return f;
            }
        } catch (final NumberFormatException nfe) { // NOPMD
            // ignore the bad number, try Double
        }
        try {
            final Double d = createDouble(numericStr);
            // FIX: Changed d.floatValue() to d.doubleValue()
            if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                return d;
            }
        } catch (final NumberFormatException nfe) { // NOPMD
            // ignore the bad number, try BigDecimal
        }

        return createBigDecimal(numericStr);
    }

public static int indexOfAny(String str, String[] searchStrs) {
        if (str == null || searchStrs == null) {
            return INDEX_NOT_FOUND;
        }

        // Special handling for an empty target string 'str'.
        // If 'str' is empty, we can only "find" an empty search string at index 0.
        // Any non-empty search string cannot be found.
        if (str.isEmpty()) {
            for (String search : searchStrs) {
                if (search != null && search.isEmpty()) {
                    return 0; // Found empty string in empty string at index 0
                }
            }
            return INDEX_NOT_FOUND; // Empty str, but no empty search string found
        }

        int ret = Integer.MAX_VALUE;

        for (String search : searchStrs) {
            // Ignore null or empty search strings for non-empty 'str'.
            // An empty string "" is "found" at index 0 by String.indexOf,
            // but this is usually not the desired behavior for indexOfAny
            // when searching for meaningful substrings in a non-empty string.
            if (search == null || search.isEmpty()) {
                continue;
            }

            int tmp = str.indexOf(search);
            if (tmp == INDEX_NOT_FOUND) {
                continue;
            }

            if (tmp < ret) {
                ret = tmp;
            }
        }

        return (ret == Integer.MAX_VALUE) ? INDEX_NOT_FOUND : ret;
    }

public static int indexOfAny(CharSequence cs, char[] searchChars) {
        // Handle null or empty CharSequence and null or empty searchChars array
        if (StringUtils.isEmpty(cs) || ArrayUtils.isEmpty(searchChars)) {
            return StringUtils.INDEX_NOT_FOUND;
        }

        int csLen = cs.length();
        int searchLen = searchChars.length;

        // Iterate through each character of the CharSequence
        for (int i = 0; i < csLen; i++) {
            char ch = cs.charAt(i);
            // For each character in CharSequence, iterate through the search characters
            for (int j = 0; j < searchLen; j++) {
                // If a match is found, return the current index
                if (searchChars[j] == ch) {
                    return i;
                }
            }
        }
        // If no character from searchChars is found in cs, return INDEX_NOT_FOUND
        return StringUtils.INDEX_NOT_FOUND;
    }

public static boolean containsAny(CharSequence cs, char[] searchChars) {
        if (StringUtils.isEmpty(cs) || ArrayUtils.isEmpty(searchChars)) {
            return false;
        }
        int csLength = cs.length();
        int searchLength = searchChars.length;
        for (int i = 0; i < csLength; i++) {
            char ch = cs.charAt(i);
            for (int j = 0; j < searchLength; j++) {
                if (searchChars[j] == ch) {
                    return true;
                }
            }
        }
        return false;
    }

public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
    // Handle null or empty CharSequence: nothing to search.
    if (isEmpty(cs)) {
        return INDEX_NOT_FOUND;
    }

    // Handle null or empty searchChars array:
    // If searchChars is empty, then any character in cs (since cs is not empty)
    // is "any but" the empty set of searchChars. So, the first character's index (0) is returned.
    if (ArrayUtils.isEmpty(searchChars)) {
        return 0;
    }

    int csLen = cs.length();
    int searchLen = searchChars.length;

    // Iterate through each character of the CharSequence 'cs'.
    outer:
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        // For each character 'ch' from 'cs', check if it exists in 'searchChars'.
        for (int j = 0; j < searchLen; j++) {
            if (searchChars[j] == ch) {
                // If 'ch' is found in 'searchChars', it means this character
                // IS one of the characters we want to exclude.
                // So, we continue to the next character in 'cs' (outer loop).
                continue outer;
            }
        }
        // If the inner loop completes without finding 'ch' in 'searchChars',
        // it means 'ch' is NOT in 'searchChars'. This is the first character
        // that is "any but" the search characters.
        return i; // Return its index.
    }

    // If the outer loop completes, it means all characters in 'cs' were found
    // within 'searchChars'. No character was found that is "any but" 'searchChars'.
    return INDEX_NOT_FOUND;
}

public static int indexOfAnyBut(String str, String searchChars) {
    if (isEmpty(str)) {
        return INDEX_NOT_FOUND;
    }
    // If str is not empty, but searchChars is empty or null,
    // then any character in str is considered "not in" searchChars.
    // Thus, the first character of str (at index 0) is the one we're looking for.
    if (isEmpty(searchChars)) {
        return 0;
    }

    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        char ch = str.charAt(i);
        // Check if the current character 'ch' is NOT found in 'searchChars'
        if (searchChars.indexOf(ch) < 0) {
            return i; // Return the index of the first character not found
        }
    }
    // If the loop completes, all characters in 'str' were found in 'searchChars'
    return INDEX_NOT_FOUND;
}

public static Class<?>[] toClass(Object[] array) {
    if (array == null) {
        return null;
    }
    // Using ArrayUtils.EMPTY_CLASS_ARRAY is good practice for empty arrays.
    // This assumes ArrayUtils is available and EMPTY_CLASS_ARRAY is defined as Class<?>[]
    if (array.length == 0) {
        return ArrayUtils.EMPTY_CLASS_ARRAY;
    }

    Class<?>[] classes = new Class[array.length];
    for (int i = 0; i < array.length; i++) {
        // Robustness improvement: Handle null elements within the input array.
        // If an element is null, its corresponding Class in the output array will also be null.
        // This prevents NullPointerException and provides a consistent output structure.
        if (array[i] == null) {
            classes[i] = null;
        } else {
            classes[i] = array[i].getClass();
        }
    }
    return classes;
}

public static boolean containsNone(CharSequence cs, char[] searchChars) {
    if (cs == null || searchChars == null) {
        return true;
    }
    int csLen = cs.length();
    int searchLen = searchChars.length;
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        for (int j = 0; j < searchLen; j++) {
            if (searchChars[j] == ch) {
                // Found a character from 'cs' that is present in 'searchChars'.
                // Therefore, 'cs' does NOT contain none of the search characters.
                return false;
            }
        }
    }
    // No character from 'cs' was found in 'searchChars'.
    // Therefore, 'cs' contains none of the search characters.
    return true;
}

public static <T> T[] add(T[] array, int index, T element) {
    Class<?> clss;

    if (array == null) {
        // If the array is null, the only valid index to add an element is 0.
        if (index != 0) {
            throw new IndexOutOfBoundsException("Cannot add to a null array at index " + index + ". Only index 0 is valid for a null array.");
        }
        // If array is null, determine the component type from the element.
        if (element != null) {
            clss = element.getClass();
        } else {
            // Both array and element are null. We cannot determine the component type
            // for the new array in a type-safe manner.
            // The original ArrayUtils returns (T[]) new Object[] { null };
            // which is type-unsafe (heap pollution).
            // A robust implementation should throw an exception.
            throw new IllegalArgumentException("Cannot determine component type when both array and element are null. " +
                                               "Provide a non-null array or element to infer the type.");
        }
    } else {
        // Array is not null. Determine component type from the existing array.
        clss = array.getClass().getComponentType();

        // Validate index for a non-null array.
        // Index must be between 0 (inclusive) and array.length (inclusive).
        if (index < 0 || index > array.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Array length: " + array.length);
        }
    }

    // Delegate to the private helper method which handles the actual array creation,
    // element insertion, and copying of existing elements.
    // The helper method is expected to create a new array of 'clss' type and size (array.length + 1).
    @SuppressWarnings("unchecked") // The private add method creates an array of type clss, which is type T
    final T[] newArray = (T[]) add(array, index, element, clss);
    return newArray;
}

public static <T> T[] add(T[] array, T element) {
        Class<?> componentType; // Renamed for clarity to reflect its actual purpose

        if (array != null) {
            // Corrected: Get the component type of the array, not the array's class itself.
            componentType = array.getClass().getComponentType();
        } else if (element != null) {
            // If array is null, infer the component type from the element.
            componentType = element.getClass();
        } else {
            // If both array and element are null, default to Object.class for the component type.
            // The resulting array will be Object[] and contain a single null element.
            componentType = Object.class;
        }

        // The copyArrayGrow1 method is assumed to handle array creation, copying,
        // and potential array size overflow checks internally.
        @SuppressWarnings("unchecked") // The componentType is derived from T[] or T, so the cast to T[] is safe at runtime.
        T[] newArray = (T[]) copyArrayGrow1(array, componentType);

        // Add the new element to the last position of the newly created array.
        newArray[newArray.length - 1] = element;

        return newArray;
    }

public static Number createNumber(String str) throws NumberFormatException {
    if (str == null) {
        return null;
    }

    // Robustness: Trim leading/trailing whitespace as standard number parsers often do.
    str = str.trim();

    if (StringUtils.isBlank(str)) {
        throw new NumberFormatException("A blank string is not a valid number.");
    }

    // Robustness: Consistent error handling for invalid number formats.
    // Protection for poorness in java.lang.BigDecimal.
    // It accepts "--" as a legal value, but it does not appear
    // to be in specification of class. OS X Java parses it to
    // a wrong value. This is an invalid number format.
    if (str.startsWith("--")) {
        throw new NumberFormatException("String '" + str + "' is not a valid number. Double negative sign is not allowed.");
    }

    // Handle hexadecimal numbers
    if (str.startsWith("0x") || str.startsWith("-0x")) {
        // createInteger is assumed to handle hex strings (e.g., via Integer.decode)
        return createInteger(str);
    }

    char lastChar = str.charAt(str.length() - 1);
    String mant;
    String dec;
    String exp;

    int decPos = str.indexOf('.');

    // Logical Fix: Correctly find the first occurrence of 'e' or 'E' for the exponent.
    int eIdx = str.indexOf('e');
    int EIdx = str.indexOf('E');
    int expPos = -1;
    if (eIdx == -1) { // No 'e' found
        expPos = EIdx;
    } else if (EIdx == -1) { // No 'E' found
        expPos = eIdx;
    } else { // Both 'e' and 'E' found, take the first one
        expPos = Math.min(eIdx, EIdx);
    }

    // Parse mantissa, decimal, and exponent parts
    if (decPos > -1) { // Has a decimal point
        if (expPos > -1) { // Has an exponent
            if (expPos < decPos) {
                // Robustness: More specific error message.
                throw new NumberFormatException("String '" + str + "' is not a valid number. Exponent cannot precede decimal point.");
            }
            dec = str.substring(decPos + 1, expPos);
        } else { // No exponent
            dec = str.substring(decPos + 1);
        }
        mant = str.substring(0, decPos);
    } else { // No decimal point
        if (expPos > -1) { // Has an exponent
            mant = str.substring(0, expPos);
        } else { // No exponent
            mant = str;
        }
        dec = null;
    }

    // Check if the last character is a digit (no explicit type suffix)
    // or if it's a type suffix (L, F, D)
    if (!Character.isDigit(lastChar)) {
        // Extract exponent part if present, excluding the type suffix
        if (expPos > -1 && expPos < str.length() - 1) {
            exp = str.substring(expPos + 1, str.length() - 1);
        } else {
            exp = null;
        }

        // The numeric string without the type suffix
        String numeric = str.substring(0, str.length() - 1);

        // Robustness: Check for empty numeric string after removing suffix (e.g., "L", "-F")
        if (numeric.isEmpty() || (numeric.length() == 1 && numeric.charAt(0) == '-')) {
             throw new NumberFormatException("String '" + str + "' is not a valid number. Missing numeric part before type suffix.");
        }

        // Helper for precision checks (assuming isAllZeros is available)
        boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

        switch (lastChar) {
            case 'l':
            case 'L':
                // For Long, no decimal or exponent is allowed.
                if (dec == null && exp == null) {
                    try {
                        return createLong(numeric);
                    } catch (NumberFormatException nfe) {
                        // If too big for a Long, try BigInteger.
                        // This handles cases like "9223372036854775807L" (max long)
                        // and "9223372036854775808L" (too big for long)
                        return createBigInteger(numeric);
                    }
                }
                // Robustness: More specific error message.
                throw new NumberFormatException("String '" + str + "' is not a valid Long number. Decimals or exponents are not allowed with 'L' suffix.");

            case 'f':
            case 'F':
                try {
                    Float f = createFloat(numeric);
                    // Logical Fix: If 'F' was explicitly requested, and Float cannot represent it
                    // accurately (infinite or significant precision loss), throw an exception.
                    if (f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)) {
                        throw new NumberFormatException("String '" + str + "' cannot be represented accurately as a Float due to overflow or precision loss.");
                    }
                    return f;
                } catch (NumberFormatException nfe) {
                    // If createFloat fails for other reasons (e.g., malformed), rethrow with context.
                    throw new NumberFormatException("String '" + str + "' is not a valid Float number.", nfe);
                }

            case 'd':
            case 'D':
                try {
                    Double d = createDouble(numeric);
                    // Logical Fix: Corrected to use d.doubleValue() for Double precision check.
                    if (d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros)) {
                        // If Double loses precision or overflows, try BigDecimal.
                        // This is a reasonable fallback for 'D' as Double is often a default.
                        return createBigDecimal(numeric);
                    }
                    return d;
                } catch (NumberFormatException nfe) {
                    // If createDouble fails, try BigDecimal as a robust fallback.
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // If BigDecimal also fails, then it's truly not a number.
                        throw new NumberFormatException("String '" + str + "' is not a valid Double or BigDecimal number.", e);
                    }
                }

            default:
                // Robustness: More specific error message for unknown suffixes.
                throw new NumberFormatException("String '" + str + "' is not a valid number. Unknown type suffix '" + lastChar + "'.");
        }
    } else { // Last character is a digit, no explicit type suffix
        // Extract exponent part if present (no type suffix to remove)
        if (expPos > -1 && expPos < str.length()) {
            exp = str.substring(expPos + 1, str.length());
        } else {
            exp = null;
        }

        if (dec == null && exp == null) {
            // Must be an int, long, or BigInteger
            try {
                return createInteger(str);
            } catch (NumberFormatException nfe) {
                // Ignore, try next type
            }
            try {
                return createLong(str);
            } catch (NumberFormatException nfe) {
                // Ignore, try next type
            }
            return createBigInteger(str); // Fallback to BigInteger
        } else {
            // Must be a float, double, or BigDecimal
            boolean allZeros = isAllZeros(mant) && isAllZeros(exp);
            try {
                Float f = createFloat(str);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                    return f;
                }
            } catch (NumberFormatException nfe) {
                // Ignore, try next type
            }
            try {
                Double d = createDouble(str);
                // Corrected: use d.doubleValue() for Double precision check.
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                    return d;
                }
            } catch (NumberFormatException nfe) {
                // Ignore, try next type
            }
            return createBigDecimal(str); // Fallback to BigDecimal
        }
    }
}

public static boolean isNumber(String str) {
    if (StringUtils.isEmpty(str)) {
        return false;
    }

    char[] chars = str.toCharArray();
    int len = chars.length;
    boolean hasExp = false;       // True if 'e' or 'E' has been encountered
    boolean hasDecPoint = false;  // True if a decimal point '.' has been encountered
    boolean allowSigns = false;   // True if a '+' or '-' is currently allowed (only after 'e'/'E')
    boolean foundDigit = false;   // True if at least one digit has been encountered

    int start = 0;
    // Handle initial sign. Only '-' is allowed at the very beginning.
    // A leading '+' is explicitly rejected by NumberUtils.isNumber.
    if (chars[0] == '-') {
        start = 1;
    }

    // Handle hexadecimal numbers (0x or 0X prefix)
    if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
        int i = start + 2;
        if (i == len) { // String is "0x" or "0X"
            return false;
        }
        // All subsequent characters must be valid hex digits
        for (; i < len; i++) {
            char c = chars[i];
            if (!((c >= '0' && c <= '9') ||
                  (c >= 'a' && c <= 'f') ||
                  (c >= 'A' && c <= 'F'))) {
                return false;
            }
        }
        return true;
    }

    // Main loop for decimal and scientific notation numbers
    for (int i = start; i < len; i++) {
        char c = chars[i];

        if (c >= '0' && c <= '9') {
            foundDigit = true;
            allowSigns = false; // A digit means no more signs are allowed until an 'e'/'E'
        } else if (c == '.') {
            // Decimal point rules:
            // 1. Only one decimal point allowed.
            // 2. No decimal point after an exponent.
            // 3. Cannot be the last character (e.g., "1." is invalid per NumberUtils.isNumber).
            if (hasDecPoint || hasExp || i == len - 1) {
                return false;
            }
            hasDecPoint = true;
            allowSigns = false; // A decimal point means no more signs are allowed
        } else if (c == 'e' || c == 'E') {
            // Exponent rules:
            // 1. Only one exponent allowed.
            // 2. Must be preceded by at least one digit.
            // 3. Cannot be the last character (e.g., "1E" is invalid).
            if (hasExp || !foundDigit || i == len - 1) {
                return false;
            }
            hasExp = true;
            allowSigns = true; // Allow a sign ('+' or '-') immediately after 'e'/'E'
            foundDigit = false; // Reset foundDigit, as a digit must follow the exponent (or its sign)
        } else if (c == '+' || c == '-') {
            // Sign rules (after exponent):
            // 1. Only allowed immediately after 'e'/'E' (checked by `allowSigns`).
            // 2. Cannot be the last character (e.g., "1E+" is invalid).
            if (!allowSigns || i == len - 1) {
                return false;
            }
            allowSigns = false; // Only one sign allowed after 'e'/'E'
            foundDigit = false; // Reset foundDigit, as a digit must follow the sign
        } else {
            // Type qualifier rules (d, D, f, F, l, L):
            // 1. Only allowed as the very last character.
            // 2. Must be preceded by at least one digit.
            // 3. 'l'/'L' cannot be used with exponents or decimal points.
            if (i == len - 1) { // Must be the last character
                if (c == 'd' || c == 'D' || c == 'f' || c == 'F') {
                    // Floating point qualifiers can follow exponents (e.g., "1e10f")
                    return foundDigit;
                }
                if (c == 'l' || c == 'L') {
                    // Long qualifiers cannot have exponents or decimal points
                    return foundDigit && !hasExp && !hasDecPoint;
                }
            }
            // Any other character, or a qualifier not at the end, makes it not a number
            return false;
        }
    }

    // If the loop completes, all characters were valid based on their position.
    // Final check: at least one digit must have been found.
    // Cases like ".", "+", "-", "e", "E" would have `foundDigit` as false and return false.
    // Cases like "1E", "1E+", "1E-", "1." are handled by `i == len - 1` checks inside the loop.
    return foundDigit;
}

public StringBuffer format(Calendar calendar, StringBuffer buf) {
        if (calendar == null) {
            throw new IllegalArgumentException("Calendar must not be null");
        }
        if (buf == null) {
            throw new IllegalArgumentException("StringBuffer must not be null");
        }

        Calendar calendarToFormat = calendar;
        if (mTimeZoneForced) {
            // Clone the calendar to avoid modifying the original object passed by the caller.
            calendarToFormat = (Calendar) calendar.clone();
            calendarToFormat.setTimeZone(mTimeZone);
        }
        return applyRules(calendarToFormat, buf);
    }

public int translate(final CharSequence input, final int index, final Writer out) throws IOException {
        // Robustness: Input validation
        if (input == null) {
            throw new IllegalArgumentException("Input CharSequence cannot be null.");
        }
        if (out == null) {
            throw new IllegalArgumentException("Writer cannot be null.");
        }
        if (index < 0) {
            throw new IndexOutOfBoundsException("Index cannot be negative: " + index);
        }
        // If the index is at or beyond the end of the input, no characters can be translated.
        // This also implicitly handles cases where input.length() is 0 and index is 0.
        if (index >= input.length()) {
            return 0;
        }

        // Calculate the effective maximum length to look up from the current index.
        // It's the smaller of the 'longest' key length defined in the translator
        // and the remaining length of the input from the current index.
        int effectiveMaxLookupLength = Math.min(this.longest, input.length() - index);

        // Descend from the longest possible match down to the shortest, implementing a greedy algorithm.
        // This ensures that if multiple keys match, the longest one is chosen.
        for (int i = effectiveMaxLookupLength; i >= this.shortest; i--) {
            // Extract the sub-sequence from the input for lookup.
            // The range is [index, index + i).
            final CharSequence subSeq = input.subSequence(index, index + i);

            // Attempt to find a translation for the sub-sequence in the lookup map.
            final CharSequence result = lookupMap.get(subSeq);

            // If a translation is found, write it to the output and return the length of the matched input.
            if (result != null) {
                out.write(result.toString());
                return i; // Return the number of characters consumed from the input
            }
        }

        // If no match is found for any length within the defined range (shortest to longest),
        // return 0, indicating no characters were consumed and no translation occurred.
        return 0;
    }

public static String getShortClassName(String className) {
        if (className == null || className.length() == 0) {
            return StringUtils.EMPTY;
        }

        StringBuilder arraySuffix = new StringBuilder();
        int arrayDepth = 0;
        while (className.charAt(arrayDepth) == '[') {
            arrayDepth++;
            arraySuffix.append("[]");
            if (arrayDepth >= className.length()) { // Malformed array name like "[[["
                return StringUtils.EMPTY;
            }
        }

        String baseClassName = className.substring(arrayDepth);

        if (arrayDepth > 0) {
            // Handle object array encoding: Ljava.lang.String;
            if (baseClassName.startsWith("L") && baseClassName.endsWith(";")) {
                baseClassName = baseClassName.substring(1, baseClassName.length() - 1); // Strip 'L' and ';'
            } else {
                // Handle primitive array encoding: I, Z, etc.
                String primitiveName = ABBREVIATION_MAP.get(baseClassName);
                if (primitiveName != null) {
                    baseClassName = primitiveName;
                }
                // If not a recognized primitive abbreviation, treat as is.
                // This covers cases like "[[Unknown" which would become "Unknown[][]"
            }
        }

        // Apply original logic to the base class name (without array dimensions)
        int lastDotIdx = baseClassName.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        // Search for inner class separator only after the package part
        int innerIdx = baseClassName.indexOf(
                INNER_CLASS_SEPARATOR_CHAR, lastDotIdx == -1 ? 0 : lastDotIdx + 1);

        String shortName = baseClassName.substring(lastDotIdx + 1);

        if (innerIdx != -1) {
            // Replace all inner class separators with package separators for readability
            shortName = shortName.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
        }

        return shortName + arraySuffix.toString();
    }

public static String getPackageName(String className) {
    if (className == null) {
        return StringUtils.EMPTY;
    }

    int i = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    if (i == -1) {
        return StringUtils.EMPTY;
    }
    return className.substring(0, i);
}

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
    // Initial parameter checks
    if (str == null) {
        return null;
    }
    if (str.length() == 0) {
        return StringUtils.EMPTY;
    }

    // --- Robustness: Normalize lower and upper parameters ---

    // Ensure 'lower' is not negative.
    // 'lower' is interpreted as the minimum index from which to start searching for a space.
    if (lower < 0) {
        lower = 0;
    }

    // Ensure 'upper' is not negative, unless it's -1 (special value for no limit).
    // 'upper' is interpreted as the maximum length of the prefix before appending 'appendToEnd'.
    if (upper < -1) {
        upper = 0; // Treat invalid negative as 0, as 0 is a sensible minimum length for abbreviation.
    }

    // If 'upper' is -1 (no limit) or is greater than the string's length,
    // set it to the string's length. This means no truncation beyond the original length.
    if (upper == -1 || upper > str.length()) {
        upper = str.length();
    }

    // If 'upper' is less than 'lower', raise 'upper' to 'lower'.
    // This ensures that the maximum prefix length is at least the starting point for word search.
    // This implicitly means 'lower' acts as a minimum effective truncation point if 'upper' is too small.
    if (upper < lower) {
        upper = lower;
    }

    // --- Logical Fix: Early exit if no abbreviation is needed ---
    // If the string's length is already less than or equal to the effective 'upper' limit,
    // no abbreviation is required. Return the original string.
    if (str.length() <= upper) {
        return str;
    }

    // --- Core Abbreviation Logic ---
    // At this point, we know str.length() > upper, so abbreviation will definitely occur.

    // Use StringBuilder for better performance in modern Java for non-thread-safe string building.
    StringBuilder result = new StringBuilder();
    // Find the first space character in 'str' starting from 'lower' index.
    int wordBreakIndex = StringUtils.indexOf(str, " ", lower);

    int truncationPoint;

    // Determine the point at which to truncate the string.
    if (wordBreakIndex == -1) {
        // Case 1: No space found from 'lower' onwards.
        // Truncate strictly at the 'upper' character limit.
        truncationPoint = upper;
    } else if (wordBreakIndex > upper) {
        // Case 2: The first space found is beyond the 'upper' character limit.
        // Truncate strictly at the 'upper' character limit.
        truncationPoint = upper;
    } else { // wordBreakIndex <= upper
        // Case 3: A space was found within or at the 'upper' character limit.
        // Truncate at this word boundary.
        truncationPoint = wordBreakIndex;
    }

    // Append the determined prefix of the string.
    result.append(str.substring(0, truncationPoint));

    // --- Logical Fix: Consistent appendToEnd application ---
    // Since we've already established that str.length() > upper, and truncationPoint <= upper,
    // it implies that truncationPoint will always be less than str.length().
    // Therefore, actual abbreviation has occurred, and 'appendToEnd' should always be appended.
    result.append(StringUtils.defaultString(appendToEnd));

    return result.toString();
}

public static void escapeJava(Writer out, String str) throws IOException {
    if (out == null) {
