    // This behavior is consistent with how some other StringEscapeUtils methods
    // handle null input when writing to a Writer (e.g., they might just do nothing).
    if (str == null) {
        return;
    }
    // Delegate to the private helper method, indicating that single quotes should not be escaped
    // when escaping for a Java double-quoted string literal.
    escapeJavaStyleString(out, str, false);
}

