    return escapeJavaStyleString(str, false);
}

public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    // Robustness: Validate width. A negative width is semantically invalid for a fixed-width operation.
    // Throw an IllegalArgumentException to clearly indicate misuse.
    if (width < 0) {
        throw new IllegalArgumentException("Width must be non-negative, but was: " + width);
    }

    // If width is 0, nothing needs to be appended. The StrBuilder's state remains unchanged.
    // This is a reasonable interpretation for a fixed width of zero.
    if (width == 0) {
        return this;
    }

    // Ensure enough capacity in the internal buffer for the new content.
    // The new content will always occupy 'width' characters.
    ensureCapacity(size + width);

    // Convert the object to its string representation.
    // If obj is null, use the StrBuilder's configured null text, consistent with other append methods.
    String str = (obj == null ? getNullText() : obj.toString());
    int strLen = str.length();

    if (strLen >= width) {
        // If the string is longer than or equal to the desired width,
        // truncate it by copying only the first 'width' characters.
        str.getChars(0, width, buffer, size);
    } else {
        // If the string is shorter than the desired width,
        // copy the entire string and then pad the remaining space on the right.
        int padLen = width - strLen; // Calculate how many padding characters are needed.
        str.getChars(0, strLen, buffer, size); // Copy the original string into the buffer.

        // Fill the remaining 'padLen' characters with the specified padChar.
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }

    // Update the size of the StrBuilder to reflect the newly appended fixed-width content.
    // The total length added to the StrBuilder is always 'width'.
    size += width;

    // Return 'this' for method chaining, allowing fluent API usage.
    return this;
}

public StrBuilder appendFixedWidthPadLeft(Object obj, int width, char padChar) {
    // Robustness: Validate width parameter. A negative width is semantically incorrect.
    if (width < 0) {
        throw new IllegalArgumentException("Width must be non-negative");
    }

    // If width is 0, there's nothing to append, so return early.
    // This also covers the case where the original method would do nothing.
    if (width == 0) {
        return this;
    }

    // Ensure enough capacity in the buffer for the fixed width.
    ensureCapacity(size + width);

    // Get the string representation of the object.
    // If obj is null, use the StrBuilder's configured nullText.
    String str = (obj == null ? getNullText() : obj.toString());

    // Robustness: Handle the case where getNullText() might return null.
    // If 'str' is null (e.g., obj was null and getNullText() returned null),
    // treat it as an empty string for length calculation and character copying.
    // This prevents NullPointerException when calling str.length() or str.getChars().
    String effectiveStr = (str == null ? "" : str);
    int strLen = effectiveStr.length();

    if (strLen >= width) {
        // If the string is longer than or equal to the desired width,
        // truncate it by taking the rightmost 'width' characters.
        effectiveStr.getChars(strLen - width, strLen, buffer, size);
    } else {
        // If the string is shorter than the desired width,
        // pad it on the left with 'padChar' and then append the string.
        int padLen = width - strLen;
        for (int i = 0; i < padLen; i++) {
            buffer[size + i] = padChar;
        }
        effectiveStr.getChars(0, strLen, buffer, size + padLen);
    }

    // Update the total size of the StrBuilder by the fixed width.
    size += width;
    return this;
}

public Fraction reduce() {
        int gcd = greatestCommonDivisor(Math.abs(numerator), denominator);
        if (gcd == 1) {
            return this;
        }
        return Fraction.getFraction(numerator / gcd, denominator / gcd);
    }

public static Locale toLocale(final String str) {
        if (str == null) {
            throw new IllegalArgumentException("Locale string must not be null.");
        }
        final int len = str.length();
        if (len < 2) { // Minimum length for a language code (e.g., "en")
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }

        String language;
        String country = ""; // Initialize to empty string, as Locale constructor handles it
        String variant = ""; // Initialize to empty string

        int firstUnderscore = str.indexOf('_');

        if (firstUnderscore == -1) { // Case: "language" (e.g., "en", "eng")
            language = str;
        } else { // Case: "language_..."
            language = str.substring(0, firstUnderscore);
            int secondUnderscore = str.indexOf('_', firstUnderscore + 1);

            if (secondUnderscore == -1) { // Case: "language_country" (e.g., "en_US")
                country = str.substring(firstUnderscore + 1);
                // If there's only one underscore, the part after it must be a 2-char country code.
                // This maintains the original method's strictness that "en_variant" is not allowed.
                if (country.length() != 2 || !Character.isUpperCase(country.charAt(0)) || !Character.isUpperCase(country.charAt(1))) {
                    throw new IllegalArgumentException("Invalid locale format: " + str);
                }
            } else { // Case: "language_country_variant" (e.g., "en_US_POSIX", "en__POSIX", "en_US_")
                country = str.substring(firstUnderscore + 1, secondUnderscore);
                variant = str.substring(secondUnderscore + 1);

                // Validate country part: must be empty or 2 uppercase chars
                if (!country.isEmpty() && (country.length() != 2 || !Character.isUpperCase(country.charAt(0)) || !Character.isUpperCase(country.charAt(1)))) {
                    throw new IllegalArgumentException("Invalid locale format: " + str);
                }
            }
        }

        // Validate language part: must be 2 or 3 lowercase characters
        if (language.length() < 2 || language.length() > 3) {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }
        for (char c : language.toCharArray()) {
            if (!Character.isLowerCase(c)) {
                throw new IllegalArgumentException("Invalid locale format: " + str);
            }
        }

        // Locale constructor handles empty strings for country and variant correctly.
        // e.g., new Locale("en", "", "POSIX") is valid.
        // e.g., new Locale("en", "US", "") is valid.
        return new Locale(language, country, variant);
    }

public static synchronized FastDateFormat getDateTimeInstance(int dateStyle, int timeStyle, TimeZone timeZone,
            Locale locale) {

        // 1. Resolve default values for timeZone and locale BEFORE cache key construction.
        //    This ensures the cache key always reflects the actual parameters used for formatting.
        final Locale resolvedLocale = (locale == null) ? Locale.getDefault() : locale;
        final TimeZone resolvedTimeZone = (timeZone == null) ? TimeZone.getDefault() : timeZone;

        // 2. Construct a consistent cache key using all four resolved parameters.
        //    Using nested Pair to represent a "quadruple" (dateStyle, timeStyle, resolvedTimeZone, resolvedLocale).
        //    This ensures the key structure is always the same, regardless of null inputs.
        Object key = new Pair(new Integer(dateStyle), new Integer(timeStyle));
        key = new Pair(key, new Pair(resolvedTimeZone, resolvedLocale));

        FastDateFormat format = cDateTimeInstanceCache.get(key);
        if (format == null) {
            try {
                // DateFormat.getDateTimeInstance uses the provided locale.
                // It implicitly uses TimeZone.getDefault() if no TimeZone is explicitly set on the returned formatter.
                // However, we will explicitly pass resolvedTimeZone to FastDateFormat.getInstance.
                SimpleDateFormat formatter = (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle,
                        resolvedLocale);
                String pattern = formatter.toPattern();

                // Use the resolved timeZone and locale when creating the FastDateFormat instance.
                // FastDateFormat.getInstance is expected to handle these parameters correctly.
                format = getInstance(pattern, resolvedTimeZone, resolvedLocale);
                cDateTimeInstanceCache.put(key, format);

            } catch (ClassCastException ex) {
                // Improved error message to reflect the actual issue more accurately.
                throw new IllegalArgumentException("Expected SimpleDateFormat from DateFormat.getDateTimeInstance, but received an incompatible type for locale: " + resolvedLocale, ex);
            }
        }
        return format;
    }

public static synchronized FastDateFormat getDateInstance(int style, TimeZone timeZone, Locale locale) {
    // Resolve the actual TimeZone and Locale to be used.
    // This ensures that if the input is null, the current JVM default is used consistently.
    final TimeZone actualTimeZone = (timeZone != null) ? timeZone : TimeZone.getDefault();
    final Locale actualLocale = (locale != null) ? locale : Locale.getDefault();

    // Construct the cache key using the resolved (actual) parameters.
    // This ensures that the cache key accurately reflects the configuration of the
    // FastDateFormat instance, preventing issues if JVM defaults change.
    Object key = Integer.valueOf(style); // Use valueOf for Integer creation
    key = new Pair(key, actualTimeZone); // Always include the actual TimeZone
    key = new Pair(key, actualLocale);   // Always include the actual Locale

    FastDateFormat format = (FastDateFormat) cDateInstanceCache.get(key);
    if (format == null) {
        try {
            // Obtain the date pattern from the JDK's DateFormat using the actual locale.
            SimpleDateFormat formatter = (SimpleDateFormat) DateFormat.getDateInstance(style, actualLocale);
            String pattern = formatter.toPattern();

            // Create the FastDateFormat instance using the resolved (actual) parameters.
            format = getInstance(pattern, actualTimeZone, actualLocale);

            // Store the newly created format in the cache with the consistent key.
            cDateInstanceCache.put(key, format);

        } catch (ClassCastException ex) {
            // Corrected error message to accurately reflect the cause of the exception.
            throw new IllegalArgumentException(
                "JDK's DateFormat.getDateInstance(style, locale) did not return a SimpleDateFormat instance " +
                "for style: " + style + ", locale: " + actualLocale + ". Cannot extract pattern.", ex);
        }
    }
    return format;
}

public static boolean toBoolean(String str) {
    // Handle null input first to prevent NullPointerExceptions and define its boolean equivalent.
    if (str == null) {
        return false;
    }

    // Convert the string to lowercase once to simplify case-insensitive comparisons.
    // This is more robust and readable than character-by-character case checks.
    String lowerStr = str.toLowerCase();

    // Explicitly check for common string representations that should map to 'true'.
    // This aligns with the documented behavior of BooleanUtils.toBoolean(String)
    // in Apache Commons Lang, which considers "true", "on", and "yes" as true.
    if ("true".equals(lowerStr)) {
        return true;
    }
    if ("on".equals(lowerStr)) {
        return true;
    }
    if ("yes".equals(lowerStr)) {
        return true;
    }

    // If the string does not match any of the "true" representations,
    // it is considered 'false'. This implicitly handles "false", "off", "no",
    // "0", "1", and any other arbitrary string as false, which is the
    // defined behavior for this specific utility method.
    return false;
}

public void stop() {
    // 1. Precondition check: Ensure the stopwatch is in a state where it can be stopped.
    // It must be either running or suspended. If it's unstarted or already stopped,
    // an IllegalStateException is thrown.
    if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
        throw new IllegalStateException("Stopwatch is not running. It must be in a RUNNING or SUSPENDED state to be stopped.");
    }

    // 2. Record the stop time only if the stopwatch was actively running.
    // If the stopwatch was suspended, its 'stopTime' should already reflect the time
    // of suspension (set by the suspend() method). The total elapsed time calculation
    // (performed by getTime()) will then correctly account for the suspended duration.
    if (this.runningState == STATE_RUNNING) {
        this.stopTime = System.currentTimeMillis();
    }

    // 3. Transition the stopwatch to the stopped state.
    this.runningState = STATE_STOPPED;

    // 4. Reset the split state. Once the stopwatch is stopped, any active split
    // is no longer relevant, ensuring a consistent state.
    this.splitState = STATE_UNSPLIT;
}

public static boolean isAvailableLocale(Locale locale) {
    // Robustness improvement: Explicitly handle null input.
    // A null locale cannot be considered an "available" locale.
    if (locale == null) {
        return false;
    }
    // Assuming cAvailableLocaleSet is guaranteed to be non-null and initialized
    // by the class's static initializer block. If there was a possibility
    // of cAvailableLocaleSet being null, an additional check would be needed here,
    // but that would indicate a deeper class initialization issue.
    return cAvailableLocaleSet.contains(locale);
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        // Replaced StringUtils.isBlank with trim().isEmpty() for self-containment
        if (str.trim().isEmpty()) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Corrected: Inconsistent error handling for "--".
        // Now throws NumberFormatException for consistency with other invalid formats.
        if (str.startsWith("--")) {
            throw new NumberFormatException("String starts with '--', which is not a valid number format.");
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            return createInteger(str);
        }

        // --- Start of parsing for mantissa, decimal, exponent for allZeros check ---
        int decPos = str.indexOf('.');
        // Corrected: Robust expPos calculation to find the first 'e' or 'E'
        int expPos = -1;
        int ePos = str.indexOf('e');
        int EPos = str.indexOf('E');

        if (ePos > -1) {
            expPos = ePos;
        }
        if (EPos > -1) {
            if (expPos == -1 || EPos < expPos) { // If 'E' is found and either 'e' wasn't or 'E' comes first
                expPos = EPos;
            }
        }

        String mant;
        String dec;
        String exp;

        // Determine the end index for the numeric part, considering a potential type suffix.
        // This ensures 'mant', 'dec', 'exp' are derived from the actual numeric portion.
        int numericPartEnd = str.length();
        char lastChar = str.charAt(str.length() - 1);
        // Check if the last character is a type suffix (L, F, D)
        if (!Character.isDigit(lastChar) && lastChar != '.' && lastChar != 'e' && lastChar != 'E' && lastChar != '-') {
            numericPartEnd--; // Exclude the suffix from the numeric part
        }

        // Extract mantissa, decimal, and exponent parts from the numeric portion of the string.
        // These parts are used for the `isAllZeros` check.
        if (decPos > -1) {
            if (expPos > -1) {
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number (exponent before decimal).");
                }
                dec = str.substring(decPos + 1, expPos);
            } else {
                dec = str.substring(decPos + 1, numericPartEnd);
            }
            mant = str.substring(0, decPos);
        } else { // No decimal point
            if (expPos > -1) {
                mant = str.substring(0, expPos);
            } else {
                mant = str.substring(0, numericPartEnd);
            }
            dec = null;
        }

        // Corrected: Ensure 'exp' is always assigned for the allZeros check.
        if (expPos > -1) {
            exp = str.substring(expPos + 1, numericPartEnd);
        } else {
            exp = null;
        }

        boolean allZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp);
        // --- End of parsing for mantissa, decimal, exponent for allZeros check ---


        // Now, proceed with the main parsing logic based on whether a suffix was detected
        if (numericPartEnd < str.length()) { // A suffix was detected
            String numeric = str.substring(0, numericPartEnd); // The number string without the suffix

            switch (lastChar) {
                case 'l':
                case 'L':
                    // Must be an integer type (no decimal, no exponent)
                    if (decPos == -1 && expPos == -1 &&
                        (numeric.charAt(0) == '-' || Character.isDigit(numeric.charAt(0))) &&
                        isDigits(numeric.substring(1))) { // isDigits checks if all chars are digits
                        try {
                            return createLong(numeric);
                        } catch (NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                        }
                        return createBigInteger(numeric);
                    }
                    throw new NumberFormatException(str + " is not a valid number (invalid 'L' suffix format).");

                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // If it's infinite OR (it's 0.0F AND the original string was not all zeros),
                        // then float does not have the precision we want, fall through.
                        if (f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)) {
                            // Fall through to double/BigDecimal
                        } else {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore the bad number, fall through
                    }
                    // Fall through to 'd' case

                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // If it's infinite OR (it's 0.0D AND the original string was not all zeros),
                        // then double does not have the precision we want, fall through.
                        if (d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros)) {
                            // Fall through to BigDecimal
                        } else {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore the bad number, fall through
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // ignore the bad number, will be caught by default
                    }
                    // Fall through to default

                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix).");
            }
        } else { // No suffix
            // User doesn't have a preference on the return type, so let's start
            // small and go from there...
            if (decPos == -1 && expPos == -1) {
                // Must be an int, long, or BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                return createBigInteger(str); // BigInteger should always parse if it's a valid integer string
            } else {
                // Must be a float, double, or BigDecimal
                try {
                    Float f = createFloat(str);
                    if (f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)) {
                        // Fall through
                    } else {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    Double d = createDouble(str);
                    if (d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros)) {
                        // Fall through
                    } else {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                return createBigDecimal(str); // BigDecimal should always parse if it's a valid decimal string
            }
        }
    }

public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    // Only proceed if a positive width is specified.
    // If width <= 0, nothing is appended, and the StrBuilder remains unchanged.
    if (width > 0) {
        // Determine the string representation of the object.
        // If obj is null, use the StrBuilder's configured null text.
        String str = (obj == null ? getNullText() : obj.toString());
        int strLen = str.length();

        // Ensure enough capacity in the internal buffer to accommodate the new fixed-width content.
        // We need space for 'width' characters.
        ensureCapacity(size + width);

        if (strLen >= width) {
            // Case 1: The string is longer than or equal to the desired fixed width.
            // Truncate the string to 'width' characters and append only those characters.
            str.getChars(0, width, buffer, size);
        } else {
            // Case 2: The string is shorter than the desired fixed width.
            // Append the entire string, then pad the remaining space on the right
            // with the specified padding character.
            int padLen = width - strLen;
            str.getChars(0, strLen, buffer, size); // Copy the original string
            for (int i = 0; i < padLen; i++) {
                buffer[size + strLen + i] = padChar; // Add padding characters
            }
        }
        // In both cases (truncation or padding), exactly 'width' characters have been
        // added to the buffer, so update the StrBuilder's size accordingly.
        size += width;
    }
    return this; // Return this StrBuilder for method chaining.
}

public int indexOf(char ch, int startIndex) {
    // Normalize startIndex: If the provided startIndex is negative,
    // adjust it to 0 to start the search from the beginning of the content.
    startIndex = (startIndex < 0 ? 0 : startIndex);

    // If the normalized startIndex is at or beyond the actual content size,
    // it means there's no valid range to search within, so the character cannot be found.
    if (startIndex >= size) {
        return -1;
    }

    // Get a local reference to the internal character buffer for efficiency.
    char[] currentBuffer = buffer;

    // Iterate from the adjusted startIndex up to the actual size of the StrBuilder's content.
    // It is crucial to use 'size' as the upper bound, not 'currentBuffer.length',
    // to ensure we only search within the valid, initialized content of the StrBuilder.
    for (int i = startIndex; i < size; i++) { // Corrected loop condition: i < size
        if (currentBuffer[i] == ch) {
            return i; // Character found at the current index.
        }
    }

    // If the loop completes without finding the character, it means it's not present
    // within the specified search range.
    return -1;
}

public boolean contains(char ch) {
    // Obtain a local reference to the internal buffer for efficiency.
    char[] thisBuf = buffer;
    // Iterate only up to the 'size' of the StrBuilder, which represents the actual
    // number of characters currently stored and considered part of its content.
    // This prevents checking uninitialized or irrelevant parts of the underlying buffer array.
    for (int i = 0; i < size; i++) {
        if (thisBuf[i] == ch) {
            return true; // Character found, return true immediately.
        }
    }
    // If the loop completes, the character was not found in the actual content.
    return false;
}

public int indexOf(String str, int startIndex) {
    // Normalize startIndex: ensure it's not negative.
    // Using Math.max for cleaner code.
    startIndex = Math.max(0, startIndex);

    // Handle null search string.
    if (str == null) {
        return -1;
    }

    // Get the length of the string to search for.
    int strLen = str.length();

    // If startIndex is at or beyond the current content size, no match is possible.
    // This also handles cases where StrBuilder is empty (size == 0) and startIndex is 0.
    if (startIndex >= size) {
        // Special case for empty search string: if startIndex is exactly size,
        // String.indexOf returns size. However, this StrBuilder's convention
        // seems to be -1 for any startIndex >= size. We maintain this.
        if (strLen == 0 && startIndex == size) {
            return size; // Aligning with String.indexOf for empty string at end
        }
        return -1;
    }

    // Optimization: If search string is a single character, delegate to the char-based indexOf.
    if (strLen == 1) {
        return indexOf(str.charAt(0), startIndex);
    }

    // Special case: Searching for an empty string.
    // An empty string is considered to be found at any valid startIndex.
    // The `startIndex >= size` check above already handles out-of-bounds `startIndex`.
    if (strLen == 0) {
        return startIndex;
    }

    // If the search string is longer than the StrBuilder's content, no match is possible.
    if (strLen > size) {
        return -1;
    }

    // Get the internal character buffer.
    char[] thisBuf = buffer;

    // Calculate the maximum possible starting index for a match.
    // The search string must fit entirely within the StrBuilder's content.
    // The last possible valid starting index is (size - strLen).
    int maxSearchIndex = size - strLen;

    // Main search loop: Iterate through possible starting positions in the StrBuilder's content.
    // The loop iterates up to and including maxSearchIndex.
    outer:
    for (int i = startIndex; i <= maxSearchIndex; i++) {
        // Inner loop: Compare characters of the search string with the StrBuilder's content.
        for (int j = 0; j < strLen; j++) {
            // If a character mismatch is found, break from the inner loop and try the next starting position.
            if (str.charAt(j) != thisBuf[i + j]) {
                continue outer;
            }
        }
        // If the inner loop completes, it means all characters matched. Return the current starting index.
        return i;
    }

    // If the outer loop completes without finding a match, return -1.
    return -1;
}

public int compareTo(Object other) {
    // Robustness: Explicitly check for null to provide a clear NullPointerException.
    // This aligns with the Comparable contract.
    if (other == null) {
        throw new NullPointerException("Cannot compare to a null object. The 'other' object must not be null.");
    }

    // Robustness: Explicitly check the type to ensure 'other' is a ValuedEnum.
    // This prevents unexpected ClassCastException later and provides a more informative message.
    // This also aligns with the Comparable contract.
    if (!(other instanceof ValuedEnum)) {
        throw new ClassCastException("Cannot compare ValuedEnum to an object of type " + other.getClass().getName() + ". Expected ValuedEnum.");
    }

    // Cast 'other' to ValuedEnum after successful type check.
    ValuedEnum otherValuedEnum = (ValuedEnum) other;

    // Logical Fix: Use Integer.compare() to safely compare integer values.
    // This avoids potential integer overflow issues that can arise from simple subtraction,
    // ensuring correct comparison results for all possible integer values.
    return Integer.compare(this.iValue, otherValuedEnum.iValue);
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }
        // Robustness: Handle multiple leading signs or other invalid prefixes more consistently.
        // A number should not start with "--".
        if (str.startsWith("--")) {
            throw new NumberFormatException(str + " is not a valid number: multiple leading signs.");
        }

        // Hexadecimal handling
        if (str.startsWith("0x") || str.startsWith("-0x") || str.startsWith("0X") || str.startsWith("-0X")) {
            try {
                // Integer.decode handles "0x", "0X", "#" prefixes and negative numbers.
                return Integer.decode(str);
            } catch (NumberFormatException e) {
                // Fall through to Long.decode if it doesn't fit in an Integer
            }
            try {
                // Long.decode handles "0x", "0X", "#" prefixes and negative numbers.
                return Long.decode(str);
            } catch (NumberFormatException e) {
                // Fall through to BigInteger if it doesn't fit in a Long
            }
            // BigInteger handles "0x" prefix if radix is specified.
            // Need to remove "0x" prefix for BigInteger(String, radix).
            String value = str.substring(str.indexOf('x') + 1);
            if (str.startsWith("-")) {
                value = "-" + value;
            }
            try {
                return new BigInteger(value, 16);
            } catch (NumberFormatException e) {
                throw new NumberFormatException(str + " is not a valid hexadecimal number.");
            }
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant;
        String dec;
        String exp;

        int decPos = str.indexOf('.');
        // Corrected: Find the first occurrence of 'e' or 'E' for the exponent position.
        int expPos = -1;
        int ePos = str.indexOf('e');
        int EPos = str.indexOf('E');

        if (ePos == -1) { // No 'e' found
            expPos = EPos;
        } else if (EPos == -1) { // No 'E' found
            expPos = ePos;
        } else { // Both 'e' and 'E' found, take the first one
            expPos = Math.min(ePos, EPos);
        }

        if (decPos > -1) { // Has a decimal point
            if (expPos > -1) { // Has an exponent
                // Logical check: exponent cannot appear before decimal point
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number: exponent before decimal point.");
                }
                dec = str.substring(decPos + 1, expPos);
            } else { // No exponent
                dec = str.substring(decPos + 1);
            }
            mant = str.substring(0, decPos);
        } else { // No decimal point
            if (expPos > -1) { // Has an exponent
                mant = str.substring(0, expPos);
            } else { // No decimal, no exponent
                mant = str;
            }
            dec = null; // No decimal part
        }

        // Corrected: Use the new helper for allZeros to include the decimal part.
        boolean allZeros = isAllNumberPartsZeros(mant, dec, exp);

        if (!Character.isDigit(lastChar) && lastChar != '.') {
            if (expPos > -1 && expPos < str.length() - 1) {
                exp = str.substring(expPos + 1, str.length() - 1);
            } else {
                exp = null;
            }
            // Requesting a specific type..
            String numeric = str.substring(0, str.length() - 1);

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (dec == null && exp == null) { // Must be an integer type
                        // Robustness: Handle empty numeric string (e.g., "L" or "-L")
                        if (numeric.isEmpty() || (numeric.length() == 1 && numeric.charAt(0) == '-')) {
                            throw new NumberFormatException(str + " is not a valid number.");
                        }
                        try {
                            return createLong(numeric);
                        } catch (NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                        }
                        return createBigInteger(numeric);
                    }
                    throw new NumberFormatException(str + " is not a valid number: 'l' or 'L' suffix with decimal or exponent.");
                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // If it's too big for a float (infinite) or it underflowed to 0.0F
                        // but the original string wasn't all zeros, then float doesn't have the precision.
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Logical fix: If createFloat explicitly failed, it's not a valid float. Propagate the exception.
                        throw new NumberFormatException(str + " is not a valid float number.");
                    }
                    // If float was valid but lacked precision, fall through to double/BigDecimal.
                    // $FALL-THROUGH$
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // If it's too big for a double (infinite) or it underflowed to 0.0D
                        // but the original string wasn't all zeros, then double doesn't have the precision.
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Logical fix: If createDouble explicitly failed, it's not a valid double. Propagate the exception.
                        throw new NumberFormatException(str + " is not a valid double number.");
                    }
                    // If double was valid but lacked precision, fall through to BigDecimal.
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // If BigDecimal also fails, then it's truly not a valid number.
                        throw new NumberFormatException(str + " is not a valid number for BigDecimal.");
                    }
                default:
                    throw new NumberFormatException(str + " is not a valid number: unknown type suffix.");
            }
        } else {
            // User doesn't have a preference on the return type, so let's start
            // small and go from there...
            if (expPos > -1 && expPos < str.length() - 1) {
                exp = str.substring(expPos + 1, str.length());
            } else {
                exp = null;
            }
            if (dec == null && exp == null) {
                // Must be an int, long, BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try next
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try next
                }
                return createBigInteger(str);

            } else {
                // Must be a float, double, BigDecimal
                // allZeros is already calculated correctly.
                try {
                    Float f = createFloat(str);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try next
                }
                try {
                    Double d = createDouble(str);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try next
                }
                return createBigDecimal(str);
            }
        }
    }
